// 자연지수 (e^x) - 테일러 급수
fn exp(x: f64) -> f64 {
  var result = 1.0
  var term = 1.0
  var n = 1.0

  var i = 0
  while i < 50 {
    term = term * x / n
    result = result + term
    if abs(term) < 1e-15 { break }
    i = i + 1
    n = n + 1.0
  }
  return result
}

// 자연로그 (ln) - 테일러 급수
fn ln(x: f64) -> f64 {
  if x <= 0.0 { return -1.0 }  // Error
  if x == 1.0 { return 0.0 }

  // x를 1에 가까운 값으로 정규화
  var n = 0.0
  var y = x
  while y > 2.0 {
    y = y / E
    n = n + 1.0
  }
  while y < 0.5 {
    y = y * E
    n = n - 1.0
  }

  // (x-1)/(x+1) 형태로 변환
  var z = (y - 1.0) / (y + 1.0)
  var z2 = z * z
  var result = 0.0
  var term = z

  var i = 0
  while i < 100 {
    result = result + term / (2.0 * f64(i) + 1.0)
    term = term * z2
    if abs(term) < 1e-15 { break }
    i = i + 1
  }

  return 2.0 * result + n
}

// 상용로그 (log10)
fn log10(x: f64) -> f64 {
  return ln(x) / ln(10.0)
}

// 2진로그 (log2)
fn log2(x: f64) -> f64 {
  return ln(x) / LN2
}

// 임의 밑의 로그
fn log(x: f64, base: f64) -> f64 {
  return ln(x) / ln(base)
}

// ============ TRIGONOMETRIC FUNCTIONS ============

// 정현파 (sin) - 테일러 급수
fn sin(x: f64) -> f64 {
  // x를 [-π, π] 범위로 정규화
  var reduced_x = x
  while reduced_x > PI {
    reduced_x = reduced_x - TAU
  }
  while reduced_x < -PI {
    reduced_x = reduced_x + TAU
  }

  var result = 0.0
  var term = reduced_x
  var x2 = reduced_x * reduced_x

  var i = 1
  while i < 50 {
    result = result + term
    term = term * (-x2) / (f64(2*i) * f64(2*i + 1))
    if abs(term) < 1e-15 { break }
    i = i + 1
  }
  return result
}

// 코사인 (cos)
fn cos(x: f64) -> f64 {
  // x를 [-π, π] 범위로 정규화
  var reduced_x = x
  while reduced_x > PI {
    reduced_x = reduced_x - TAU
  }
  while reduced_x < -PI {
    reduced_x = reduced_x + TAU
  }

  var result = 1.0
  var term = 1.0
  var x2 = reduced_x * reduced_x

  var i = 1
  while i < 50 {
    term = term * (-x2) / (f64(2*i - 1) * f64(2*i))
    result = result + term
    if abs(term) < 1e-15 { break }
    i = i + 1
  }
  return result
}

// 탄젠트 (tan)
fn tan(x: f64) -> f64 {
  var c = cos(x)
  if abs(c) < 1e-15 { return 0.0 }  // undefined
  return sin(x) / c
}

// 역정현 (asin)
fn asin(x: f64) -> f64 {
  if abs(x) > 1.0 { return 0.0 }  // Error
  if x == 0.0 { return 0.0 }

  var result = x
  var numerator = x
  var denominator = 1.0
  var x2 = x * x

  var n = 1
  while n < 50 {
    numerator = numerator * x2 * f64(2*n - 1) / f64(2*n)
    denominator = f64(2*n + 1)
    result = result + numerator / denominator
    if abs(numerator) < 1e-15 { break }
    n = n + 1
  }
  return result
}

// 역코사인 (acos)
fn acos(x: f64) -> f64 {
  return PI / 2.0 - asin(x)
}

// 역탄젠트 (atan)
fn atan(x: f64) -> f64 {
  if abs(x) > 1.0 {
    return sign(x) * (PI / 2.0) - atan(1.0 / x)
  }

  var result = 0.0
  var x_power = x
  var x2 = x * x

  var n = 0
  while n < 50 {
    result = result + x_power / f64(2*n + 1)
    x_power = x_power * (-x2)
    if abs(x_power) < 1e-15 { break }
    n = n + 1
  }
  return result
}

// 두 변수 역탄젠트 (atan2)
fn atan2(y: f64, x: f64) -> f64 {
  if x > 0.0 { return atan(y / x) }
  if x < 0.0 && y >= 0.0 { return atan(y / x) + PI }
  if x < 0.0 && y < 0.0 { return atan(y / x) - PI }
  if x == 0.0 && y > 0.0 { return PI / 2.0 }
  if x == 0.0 && y < 0.0 { return -PI / 2.0 }
  return 0.0  // undefined
}

// ============ HYPERBOLIC FUNCTIONS ============

// 쌍곡선 정현 (sinh)
fn sinh(x: f64) -> f64 {
  return (exp(x) - exp(-x)) / 2.0
}

// 쌍곡선 코사인 (cosh)
fn cosh(x: f64) -> f64 {
  return (exp(x) + exp(-x)) / 2.0
}

// 쌍곡선 탄젠트 (tanh)
fn tanh(x: f64) -> f64 {
  var e2x = exp(2.0 * x)
  return (e2x - 1.0) / (e2x + 1.0)
}

// ============ SPECIAL FUNCTIONS ============

// 최대공약수 (GCD)
fn gcd(a: i64, b: i64) -> i64 {
  if b == 0 { return a }
  return gcd(b, a % b)
}

// 최소공배수 (LCM)
fn lcm(a: i64, b: i64) -> i64 {
  return (a * b) / gcd(a, b)
}

// 계승 (factorial)
fn factorial(n: i64) -> i64 {
  if n <= 1 { return 1 }
  return n * factorial(n - 1)
}

// 조합 nCr
fn combination(n: i64, r: i64) -> i64 {
  if r > n { return 0 }
  if r == 0 || r == n { return 1 }
  return factorial(n) / (factorial(r) * factorial(n - r))
}

// 순열 nPr
fn permutation(n: i64, r: i64) -> i64 {
  if r > n { return 0 }
  return factorial(n) / factorial(n - r)
}

// ============ VECTOR OPERATIONS (배열 연산) ============

// 벡터 크기 (norm)
fn vector_norm(v: f64[]) -> f64 {
  var sum = 0.0
  var i = 0
  while i < len(v) {
    sum = sum + v[i] * v[i]
    i = i + 1
  }
  return sqrt(sum)
}

// 벡터 내적 (dot product)
fn dot_product(a: f64[], b: f64[]) -> f64 {
  var result = 0.0
  var i = 0
  var len_a = len(a)
  while i < len_a {
    result = result + a[i] * b[i]
    i = i + 1
  }
  return result
}

// 벡터 스칼라 곱셈
fn scalar_multiply(v: f64[], scalar: f64) -> f64[] {
  var result: f64[] = [0.0]
  var i = 0
  while i < len(v) {
    push(result, v[i] * scalar)
    i = i + 1
  }
  pop(result)  // 초기 0.0 제거
  return result
}

// ============ END OF MATH MODULE ============

