fn is_prime(n: i64) -> bool {
  if n < 2 {
    return false
  }
  if n == 2 {
    return true
  }
  if n % 2 == 0 {
    return false
  }

  let mut i = 3
  while i * i <= n {
    if n % i == 0 {
      return false
    }
    i = i + 2
  }
  return true
}

fn main() -> void {
  println("Primes up to 50:")
