		Currency:        account.Currency,
		Type:            "deposit",
		Description:     "입금",
		Status:          "confirmed",
		Fee:             0.0,
	}
	database.CreateTransaction(tx)

	// 감시 로그
	database.LogAudit(&db.AuditLog{
		ID:           uuid.New().String(),
		UserID:       userID,
