   708→        // ==================== Auth ====================
   709→
   710→        async function login() {
   711→            const email = document.getElementById('loginEmail').value;
   712→            const password = document.getElementById('loginPassword').value;
   713→
   714→            if (!email || !password) {
   715→                showError('이메일과 비밀번호를 입력하세요');
   716→                return;
   717→            }
   718→
   719→            try {
   720→                const response = await fetch(`${API_URL}/auth/login`, {
   721→                    method: 'POST',
   722→                    headers: { 'Content-Type': 'application/json' },
   723→                    body: JSON.stringify({ email, password })
   724→                });
   725→
   726→                const data = await response.json();
   727→
   728→                if (!response.ok) {
   729→                    showError(data.error || '로그인 실패');
   730→                    return;
   731→                }
   732→
   733→                localStorage.setItem('token', data.token);
   734→                localStorage.setItem('email', data.email);
   735→
   736→                token = data.token;
   737→                userEmail = data.email;
   738→
   739→                document.getElementById('loginEmail').value = '';
   740→                document.getElementById('loginPassword').value = '';
   741→                document.getElementById('userEmail').textContent = userEmail;
   742→
   743→                showPage('dashboardPage');
   744→                loadAccounts();
   745→            } catch (error) {
   746→                showError('서버 오류: ' + error.message);
   747→            }
   748→        }
   749→
   750→        async function register() {
   751→            const email = document.getElementById('registerEmail').value;
   752→            const password = document.getElementById('registerPassword').value;
   753→            const firstName = document.getElementById('registerFirstName').value;
   754→            const lastName = document.getElementById('registerLastName').value;
   755→
   756→            if (!email || !password || password.length < 6) {
   757→                showError('올바른 정보를 입력하세요');
   758→                return;
   759→            }
   760→
   761→            try {
   762→                const response = await fetch(`${API_URL}/auth/register`, {
   763→                    method: 'POST',
   764→                    headers: { 'Content-Type': 'application/json' },
   765→                    body: JSON.stringify({ email, password, first_name: firstName, last_name: lastName })
   766→                });
   767→
   768→                const data = await response.json();
   769→
   770→                if (!response.ok) {
   771→                    showError(data.error || '회원가입 실패');
   772→                    return;
   773→                }
   774→
   775→                document.getElementById('registerSuccess').textContent = '회원가입 성공! 로그인해주세요.';
   776→                document.getElementById('registerSuccess').classList.add('show');
   777→
   778→                document.getElementById('registerEmail').value = '';
   779→                document.getElementById('registerPassword').value = '';
   780→                document.getElementById('registerFirstName').value = '';
   781→                document.getElementById('registerLastName').value = '';
   782→
   783→                setTimeout(() => switchTab('login'), 1500);
   784→            } catch (error) {
   785→                showError('서버 오류: ' + error.message);
   786→            }
   787→        }
