   798→        // ==================== Accounts ====================
   799→
   800→        async function loadAccounts() {
   801→            try {
   802→                const response = await fetch(`${API_URL}/accounts`, {
   803→                    headers: { 'Authorization': `Bearer ${token}` }
   804→                });
   805→
   806→                const data = await response.json();
   807→                accounts = data.accounts || [];
   808→
   809→                renderAccounts();
   810→                updateStatistics();
   811→                updateAccountSelects();
   812→            } catch (error) {
   813→                console.error('계좌 로드 오류:', error);
   814→            }
   815→        }
   816→
   817→        function renderAccounts() {
   818→            const list = document.getElementById('accountsList');
   819→            if (!accounts.length) {
   820→                list.innerHTML = '<li style="text-align: center; color: #999;">계좌가 없습니다</li>';
   821→                return;
   822→            }
   823→
   824→            list.innerHTML = accounts.map(acc => `
   825→                <li class="account-item">
   826→                    <div class="account-type">${acc.account_type}</div>
   827→                    <div class="account-id">${acc.id.substring(0, 8)}...</div>
   828→                    <div class="account-balance">$${acc.balance.toFixed(2)}</div>
   829→                </li>
   830→            `).join('');
   831→        }
   832→
   833→        function updateStatistics() {
   834→            const totalAccounts = accounts.length;
   835→            const totalBalance = accounts.reduce((sum, acc) => sum + acc.balance, 0);
   836→
   837→            document.getElementById('totalAccounts').textContent = totalAccounts;
   838→            document.getElementById('totalBalance').textContent = '$' + totalBalance.toFixed(2);
   839→        }
   840→
   841→        function updateAccountSelects() {
   842→            const selects = ['fromAccount', 'toAccount', 'depositAccount', 'withdrawAccount', 'accountFilter'];
   843→            const options = accounts.map(acc => `<option value="${acc.id}">${acc.account_type} - $${acc.balance.toFixed(2)}</option>`).join('');
   844→
   845→            selects.forEach(id => {
   846→                const select = document.getElementById(id);
   847→                if (select) {
   848→                    const currentValue = select.value;
   849→                    select.innerHTML = '<option value="">계좌 선택</option>' + options;
   850→                    if (currentValue) select.value = currentValue;
   851→                }
   852→            });
   853→        }
