   855→        async function createAccount() {
   856→            const type = document.getElementById('accountType').value;
   857→
   858→            try {
   859→                const response = await fetch(`${API_URL}/accounts`, {
   860→                    method: 'POST',
   861→                    headers: {
   862→                        'Content-Type': 'application/json',
   863→                        'Authorization': `Bearer ${token}`
   864→                    },
   865→                    body: JSON.stringify({ account_type: type, currency: 'USD' })
   866→                });
   867→
   868→                const data = await response.json();
   869→
   870→                if (!response.ok) {
   871→                    alert('계좌 생성 실패: ' + (data.error || '오류'));
   872→                    return;
   873→                }
   874→
   875→                closeModal('createAccountModal');
   876→                loadAccounts();
   877→            } catch (error) {
   878→                alert('오류: ' + error.message);
   879→            }
   880→        }
