   882→        async function deposit() {
   883→            const accountId = document.getElementById('depositAccount').value;
   884→            const amount = parseFloat(document.getElementById('depositAmount').value);
   885→
   886→            if (!accountId || !amount || amount <= 0) {
   887→                alert('올바른 정보를 입력하세요');
   888→                return;
   889→            }
   890→
   891→            try {
   892→                const response = await fetch(`${API_URL}/accounts/${accountId}/deposit`, {
   893→                    method: 'POST',
   894→                    headers: {
   895→                        'Content-Type': 'application/json',
   896→                        'Authorization': `Bearer ${token}`
   897→                    },
   898→                    body: JSON.stringify({ amount })
   899→                });
   900→
   901→                const data = await response.json();
   902→
   903→                if (!response.ok) {
   904→                    alert('입금 실패: ' + (data.error || '오류'));
   905→                    return;
