     1→/**
     2→ * FreeLang Playground Backend Server
     3→ * Handles code compilation, execution, and sharing
     4→ */
     5→
     6→const express = require('express');
     7→const cors = require('cors');
     8→const bodyParser = require('body-parser');
     9→const { exec } = require('child_process');
    10→const fs = require('fs');
    11→const path = require('path');
    12→const crypto = require('crypto');
    13→
    14→const app = express();
    15→const PORT = process.env.PORT || 3000;
    16→
    17→// Middleware
    18→app.use(cors());
    19→app.use(bodyParser.json({ limit: '50mb' }));
    20→app.use(bodyParser.urlencoded({ limit: '50mb', extended: true }));
    21→
    22→// 코드 저장 디렉토리
    23→const CODE_DIR = path.join(__dirname, '.codes');
    24→const SHARE_DIR = path.join(__dirname, '.share');
    25→
    26→// 디렉토리 생성
    27→if (!fs.existsSync(CODE_DIR)) {
    28→  fs.mkdirSync(CODE_DIR, { recursive: true });
    29→}
    30→if (!fs.existsSync(SHARE_DIR)) {
    31→  fs.mkdirSync(SHARE_DIR, { recursive: true });
    32→}
    33→
    34→// ============ API ENDPOINTS ============
    35→
    36→/**
    37→ * Health Check
    38→ */
    39→app.get('/api/health', (req, res) => {
    40→  res.json({
    41→    status: 'ok',
    42→    timestamp: new Date().toISOString(),
    43→    version: '1.0.0'
    44→  });
    45→});
    46→
    47→/**
    48→ * 코드 컴파일
    49→ * POST /api/compile
    50→ * Body: { code: string, language: string }
    51→ */
    52→app.post('/api/compile', (req, res) => {
    53→  try {
    54→    const { code, language = 'freelang' } = req.body;
    55→
    56→    if (!code) {
    57→      return res.status(400).json({
    58→        success: false,
    59→        error: 'Code is required'
    60→      });
    61→    }
    62→
    63→    // 임시 파일 생성
    64→    const filename = `code_${Date.now()}.fl`;
    65→    const filepath = path.join(CODE_DIR, filename);
    66→
    67→    fs.writeFileSync(filepath, code);
    68→
    69→    // 컴파일 실행 (freelang 컴파일러)
    70→    exec(`freelang compile ${filepath}`, (error, stdout, stderr) => {
    71→      fs.unlinkSync(filepath);
    72→
    73→      if (error) {
    74→        return res.json({
    75→          success: false,
    76→          error: stderr || error.message,
    77→          stdout
    78→        });
    79→      }
    80→
    81→      res.json({
    82→        success: true,
    83→        output: stdout,
    84→        compilationTime: new Date().toISOString()
    85→      });
    86→    });
    87→  } catch (error) {
    88→    res.status(500).json({
    89→      success: false,
    90→      error: error.message
    91→    });
    92→  }
    93→});
    94→
    95→/**
    96→ * 코드 실행
    97→ * POST /api/run
    98→ * Body: { code: string, timeout: number }
    99→ */
   100→app.post('/api/run', (req, res) => {
   101→  try {
   102→    const { code, timeout = 5000 } = req.body;
   103→
   104→    if (!code) {
   105→      return res.status(400).json({
   106→        success: false,
   107→        error: 'Code is required'
   108→      });
   109→    }
   110→
   111→    // 임시 파일 생성
   112→    const filename = `code_${Date.now()}.fl`;
   113→    const filepath = path.join(CODE_DIR, filename);
   114→
   115→    fs.writeFileSync(filepath, code);
   116→
   117→    // 코드 실행
   118→    const startTime = Date.now();
   119→
   120→    exec(`freelang run ${filepath}`, { timeout }, (error, stdout, stderr) => {
   121→      fs.unlinkSync(filepath);
   122→
   123→      const executionTime = Date.now() - startTime;
   124→
   125→      if (error) {
   126→        return res.json({
   127→          success: false,
   128→          error: stderr || error.message,
   129→          stdout,
   130→          executionTime,
   131→          timedOut: error.killed
   132→        });
   133→      }
   134→
   135→      res.json({
   136→        success: true,
   137→        output: stdout,
   138→        executionTime,
   139→        stderr: stderr || null
   140→      });
   141→    });
   142→  } catch (error) {
   143→    res.status(500).json({
   144→      success: false,
   145→      error: error.message
   146→    });
   147→  }
   148→});
   149→
   150→/**
   151→ * 코드 공유
   152→ * POST /api/share
   153→ * Body: { code: string, title: string, description: string }
   154→ */
   155→app.post('/api/share', (req, res) => {
   156→  try {
   157→    const { code, title = 'Untitled', description = '', tags = [] } = req.body;
   158→
   159→    if (!code) {
   160→      return res.status(400).json({
   161→        success: false,
   162→        error: 'Code is required'
   163→      });
   164→    }
   165→
   166→    // 고유 ID 생성
   167→    const shareId = crypto.randomBytes(8).toString('hex');
   168→    const timestamp = new Date().toISOString();
   169→
   170→    const shareData = {
   171→      id: shareId,
   172→      code,
   173→      title,
   174→      description,
   175→      tags,
   176→      createdAt: timestamp,
   177→      updatedAt: timestamp,
   178→      views: 0,
   179→      url: `${req.protocol}://${req.get('host')}/playground?share=${shareId}`
   180→    };
   181→
   182→    // 공유 코드 저장
   183→    fs.writeFileSync(
   184→      path.join(SHARE_DIR, `${shareId}.json`),
   185→      JSON.stringify(shareData, null, 2)
   186→    );
   187→
   188→    res.json({
   189→      success: true,
   190→      shareId,
   191→      url: shareData.url
   192→    });
   193→  } catch (error) {
   194→    res.status(500).json({
   195→      success: false,
   196→      error: error.message
   197→    });
   198→  }
   199→});
   200→
   201→/**
   202→ * 공유 코드 조회
   203→ * GET /api/share/:shareId
   204→ */
   205→app.get('/api/share/:shareId', (req, res) => {
   206→  try {
   207→    const { shareId } = req.params;
   208→    const filepath = path.join(SHARE_DIR, `${shareId}.json`);
   209→
   210→    if (!fs.existsSync(filepath)) {
   211→      return res.status(404).json({
   212→        success: false,
   213→        error: 'Share not found'
   214→      });
   215→    }
   216→
   217→    const shareData = JSON.parse(fs.readFileSync(filepath, 'utf8'));
   218→
   219→    // 조회수 증가
   220→    shareData.views = (shareData.views || 0) + 1;
   221→    shareData.updatedAt = new Date().toISOString();
   222→    fs.writeFileSync(filepath, JSON.stringify(shareData, null, 2));
   223→
   224→    res.json({
   225→      success: true,
   226→      data: shareData
   227→    });
   228→  } catch (error) {
   229→    res.status(500).json({
   230→      success: false,
   231→      error: error.message
   232→    });
   233→  }
   234→});
   235→
   236→/**
   237→ * 모든 공유 코드 목록
   238→ * GET /api/shares?page=1&limit=10&sort=views
   239→ */
   240→app.get('/api/shares', (req, res) => {
   241→  try {
   242→    const { page = 1, limit = 10, sort = 'views' } = req.query;
   243→    const offset = (parseInt(page) - 1) * parseInt(limit);
   244→
