     1→/**
     2→ * FreeLang Playground Backend Server
     3→ * Handles code compilation, execution, and sharing
     4→ */
     5→
     6→const express = require('express');
     7→const cors = require('cors');
     8→const bodyParser = require('body-parser');
     9→const { exec } = require('child_process');
    10→const fs = require('fs');
    11→const path = require('path');
    12→const crypto = require('crypto');
    13→
    14→const app = express();
    15→const PORT = process.env.PORT || 3000;
    16→
    17→// Middleware
    18→app.use(cors());
    19→app.use(bodyParser.json({ limit: '50mb' }));
    20→app.use(bodyParser.urlencoded({ limit: '50mb', extended: true }));
    21→
    22→// 코드 저장 디렉토리
    23→const CODE_DIR = path.join(__dirname, '.codes');
    24→const SHARE_DIR = path.join(__dirname, '.share');
    25→
    26→// 디렉토리 생성
    27→if (!fs.existsSync(CODE_DIR)) {
    28→  fs.mkdirSync(CODE_DIR, { recursive: true });
    29→}
    30→if (!fs.existsSync(SHARE_DIR)) {
    31→  fs.mkdirSync(SHARE_DIR, { recursive: true });
    32→}
    33→
    34→// ============ API ENDPOINTS ============
    35→
    36→/**
    37→ * Health Check
    38→ */
    39→app.get('/api/health', (req, res) => {
    40→  res.json({
    41→    status: 'ok',
    42→    timestamp: new Date().toISOString(),
    43→    version: '1.0.0'
    44→  });
    45→});
    46→
    47→/**
    48→ * 코드 컴파일
    49→ * POST /api/compile
    50→ * Body: { code: string, language: string }
    51→ */
    52→app.post('/api/compile', (req, res) => {
    53→  try {
    54→    const { code, language = 'freelang' } = req.body;
    55→
    56→    if (!code) {
    57→      return res.status(400).json({
    58→        success: false,
    59→        error: 'Code is required'
    60→      });
    61→    }
    62→
    63→    // 임시 파일 생성
    64→    const filename = `code_${Date.now()}.fl`;
    65→    const filepath = path.join(CODE_DIR, filename);
    66→
    67→    fs.writeFileSync(filepath, code);
    68→
    69→    // 컴파일 실행 (freelang 컴파일러)
    70→    exec(`freelang compile ${filepath}`, (error, stdout, stderr) => {
    71→      fs.unlinkSync(filepath);
    72→
    73→      if (error) {
    74→        return res.json({
    75→          success: false,
    76→          error: stderr || error.message,
    77→          stdout
    78→        });
    79→      }
