    22→  cycles: number;
    23→  time: number;
    24→}
    25→
    26→export class V3Engine {
    27→  private vm = new VM();
    28→  private patterns = new PatternLibrary();
    29→  private execCount = 0;
    30→
    31→  /**
    32→   * AI가 intent를 실행 (완전 자동)
    33→   */
    34→  async execute(intent: string, variables?: Record<string, any>): Promise<ExecutionResult> {
    35→    this.execCount++;
    36→    console.log(`\n[${this.execCount}] "${intent}"`);
    37→
    38→    // 1. 패턴 검색
    39→    let pattern = this.patterns.find(intent);
    40→    let cached = false;
    41→
    42→    if (pattern) {
    43→      console.log(`  ✓ From cache (confidence: ${pattern.confidence.toFixed(2)})`);
    44→      cached = true;
    45→    } else {
    46→      // 유사 패턴 검색
    47→      const similar = this.patterns.findSimilar(intent, 0.6);
    48→      if (similar.length > 0) {
    49→        console.log(`  → Similar: ${similar[0].intent}`);
    50→      }
    51→
    52→      // 2. IR 생성
    53→      console.log(`  ⚙️  Generating IR...`);
    54→      const program = this.generateIR(intent);
    55→
    56→      // 패턴으로 저장
    57→      pattern = {
    58→        id: `p_${Date.now()}`,
    59→        intent,
    60→        ir: program.instructions,
    61→        variants: [],
    62→        stats: {
    63→          successCount: 0,
    64→          failCount: 0,
    65→          avgCycles: 0,
    66→          minCycles: Number.MAX_SAFE_INTEGER,
    67→          lastUsed: Date.now()
    68→        },
    69→        confidence: 0.5
    70→      };
    71→
    72→      this.patterns.add(pattern);
    73→    }
    74→
    75→    // 3. IR 프로그램 생성
    76→    const program: IRProgram = {
    77→      id: pattern.id,
    78→      intent,
    79→      instructions: pattern.ir,
    80→      metadata: { variant: 0, generated: Date.now(), confidence: pattern.confidence }
    81→    };
    82→
    83→    // 4. VM 실행 (변수와 함께)
    84→    console.log(`  🚀 Running...`);
    85→    const vmResult = this.vm.run(program, variables);
    86→
    87→    // 6. 결과 처리
    88→    if (vmResult.ok) {
    89→      console.log(`  ✅ Result: ${JSON.stringify(vmResult.value)}`);
    90→      console.log(`  📊 Cycles: ${vmResult.metrics.cycles}, Time: ${vmResult.metrics.time}ms`);
    91→
    92→      // 7. 패턴 학습
    93→      this.patterns.update(pattern.id, vmResult.metrics, true);
    94→
    95→      return {
    96→        value: vmResult.value,
    97→        cached,
    98→        cycles: vmResult.metrics.cycles,
    99→        time: vmResult.metrics.time
   100→      };
   101→    } else {
   102→      console.log(`  ❌ Error: ${vmResult.error}`);
   103→
   104→      // 실패도 학습
   105→      this.patterns.update(pattern.id, vmResult.metrics, false);
   106→
   107→      throw new Error(vmResult.error);
   108→    }
   109→  }
   110→
   111→  /**
   112→   * Intent → IR 자동 생성 (AI가 함)
   113→   */
   114→  private generateIR(intent: string): IRProgram {
   115→    const words = intent.toLowerCase().split(/\s+/);
   116→
   117→    const instructions: Inst[] = [];
   118→
   119→    // "sum array"
   120→    if (words.includes('sum')) {
   121→      instructions.push(ir.load('arr'));
   122→      instructions.push(ir.arrSum());
   123→    }
   124→    // "find max"
   125→    else if (words.includes('max')) {
   126→      instructions.push(ir.load('arr'));
   127→      instructions.push(ir.arrMax());
   128→    }
   129→    // "find min"
   130→    else if (words.includes('min')) {
   131→      instructions.push(ir.load('arr'));
   132→      instructions.push(ir.arrMin());
   133→    }
   134→    // "length"
   135→    else if (words.includes('length') || words.includes('size')) {
   136→      instructions.push(ir.load('arr'));
   137→      instructions.push(ir.arrLen());
   138→    }
   139→    // fallback: 숫자들
   140→    else {
   141→      const nums = intent.match(/\d+/g);
   142→      if (nums && nums.length > 0) {
   143→        for (const n of nums) {
   144→          instructions.push(ir.push(parseInt(n)));
   145→        }
   146→        if (words.includes('add') || words.includes('plus')) {
   147→          instructions.push({ op: Op.ADD });
   148→        }
   149→      }
   150→    }
   151→
   152→    if (instructions.length === 0) {
   153→      instructions.push(ir.push(0));
   154→    }
   155→
   156→    instructions.push(ir.halt());
   157→
   158→    return {
   159→      id: `prog_${Date.now()}`,
   160→      intent,
   161→      instructions,
   162→      metadata: { variant: 0, generated: Date.now(), confidence: 0.5 }
   163→    };
   164→  }
   165→
   166→  /**
   167→   * 통계 출력
   168→   */
   169→  stats() {
   170→    const s = this.patterns.stats();
   171→    console.log(`\n📊 Pattern Library:`);
   172→    console.log(`   Patterns: ${s.patterns}`);
   173→    console.log(`   Success rate: ${(s.successRate * 100).toFixed(1)}%`);
   174→    console.log(`   Avg cycles: ${s.avgCycles.toFixed(0)}`);
   175→  }
   176→}
   177→
   178→// ============================================
   179→// 테스트
   180→// ============================================
   181→
   182→async function demo() {
