   195→    const r2 = await engine.execute('sum array', { arr: [10, 20] });
   196→    console.log(`Result: ${r2.value}, Cached: ${r2.cached}`);
   197→  } catch (e: any) {
   198→    console.error(e.message);
   199→  }
   200→
   201→  // Test 3
   202→  try {
   203→    const r3 = await engine.execute('find max', { arr: [5, 2, 8, 1] });
   204→    console.log(`Result: ${r3.value}`);
   205→  } catch (e: any) {
   206→    console.error(e.message);
   207→  }
   208→
   209→  // 통계
   210→  engine.stats();
