  IDENTIFIER = 'IDENTIFIER',
  KEYWORD = 'KEYWORD',

  // 연산자
  PLUS = 'PLUS',
  MINUS = 'MINUS',
  STAR = 'STAR',
  SLASH = 'SLASH',
  EQ = 'EQ',
  NE = 'NE',
  LT = 'LT',
  LE = 'LE',
  GT = 'GT',
  GE = 'GE',
  ASSIGN = 'ASSIGN',
  AND = 'AND',
  OR = 'OR',

  // 기호
  LPAREN = 'LPAREN',      // (
  RPAREN = 'RPAREN',      // )
