  COLON = 'COLON',        // :
  COMMA = 'COMMA',        // ,
  ARROW = 'ARROW',        // ->
  DOT = 'DOT',            // .

  // 특수
  INDENT = 'INDENT',
  DEDENT = 'DEDENT',
  NEWLINE = 'NEWLINE',
  EOF = 'EOF',
