/**
 * V3 Test Runner (JavaScript)
 * TypeScript 없이 직접 V3 파일 테스트
 */

const fs = require('fs');
const path = require('path');

class V3Lexer {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
    this.indentStack = [0];
    this.lineStart = true;
  }

  tokenize() {
    while (this.pos < this.source.length) {
      this.skipWhitespaceOnLine();

      if (this.isNewline()) {
        this.consumeNewline();
        this.lineStart = true;
        continue;
      }

      if (this.isComment()) {
        this.skipComment();
        continue;
      }

      if (this.lineStart && !this.isNewline()) {
        this.handleIndentation();
        this.lineStart = false;
      }

      if (this.pos >= this.source.length) break;

      const ch = this.peek();

      if (ch === '"' || ch === "'") {
        this.consumeString();
        continue;
      }

      if (this.isDigit(ch)) {
        this.consumeNumber();
        continue;
      }

      if (this.isLetter(ch) || ch === '_') {
        this.consumeIdentifierOrKeyword();
        continue;
      }

      if (!this.consumeOperatorOrSymbol()) {
        throw new Error(`미인식 문자 '${ch}' at line ${this.line}, column ${this.column}`);
      }
    }

    while (this.indentStack.length > 1) {
      this.indentStack.pop();
      this.addToken('DEDENT', null);
    }

    this.addToken('EOF', null);
    return this.tokens;
  }

  handleIndentation() {
    let spaces = 0;
    while (this.pos < this.source.length && this.peek() === ' ') {
      spaces++;
      this.pos++;
      this.column++;
    }

    const currentIndent = this.indentStack[this.indentStack.length - 1];

    if (spaces > currentIndent) {
      this.indentStack.push(spaces);
      this.addToken('INDENT', null);
    } else if (spaces < currentIndent) {
      while (this.indentStack.length > 1 && this.indentStack[this.indentStack.length - 1] > spaces) {
        this.indentStack.pop();
        this.addToken('DEDENT', null);
      }
    }
  }

  consumeString() {
    const quote = this.peek();
    const startLine = this.line;
    this.pos++;
    this.column++;

    let value = '';
    while (this.pos < this.source.length && this.peek() !== quote) {
      if (this.peek() === '\\' && this.peekNext() === quote) {
        this.pos += 2;
        this.column += 2;
        value += quote;
      } else if (this.peek() === '\\' && this.peekNext() === 'n') {
        this.pos += 2;
        this.column += 2;
        value += '\n';
      } else {
        value += this.peek();
        this.pos++;
        this.column++;
      }
    }

    if (this.pos >= this.source.length) {
      throw new Error(`닫히지 않은 문자열 at line ${startLine}`);
    }

    this.pos++;
    this.column++;
    this.addToken('STRING', value);
  }

  consumeNumber() {
    let value = '';
    while (this.pos < this.source.length && this.isDigit(this.peek())) {
      value += this.peek();
      this.pos++;
      this.column++;
    }

    if (this.peek() === '.' && this.isDigit(this.peekNext())) {
      value += '.';
      this.pos++;
      this.column++;
      while (this.pos < this.source.length && this.isDigit(this.peek())) {
        value += this.peek();
        this.pos++;
        this.column++;
      }
    }

    this.addToken('NUMBER', parseFloat(value));
  }

  consumeIdentifierOrKeyword() {
    let value = '';
    while (
      this.pos < this.source.length &&
      (this.isLetter(this.peek()) || this.isDigit(this.peek()) || this.peek() === '_')
    ) {
      value += this.peek();
      this.pos++;
      this.column++;
    }

    const KEYWORDS = new Set([
      'ARR', 'INT', 'STR', 'BOOL', 'FLOAT',
      'ARR_SUM', 'ARR_AVG', 'ARR_MAX', 'ARR_MIN',
      'IF', 'ELSE', 'FOR', 'IN', 'WHILE',
      'FUNC', 'RETURN', 'CALL',
      'TRUE', 'FALSE', 'NONE', 'PRINTLN',
    ]);

    if (KEYWORDS.has(value)) {
      if (value === 'TRUE') {
        this.addToken('BOOL', true);
      } else if (value === 'FALSE') {
        this.addToken('BOOL', false);
      } else {
        this.addToken('KEYWORD', value);
      }
    } else {
      this.addToken('IDENTIFIER', value);
    }
  }

  consumeOperatorOrSymbol() {
    const ch = this.peek();
    const next = this.peekNext();

    if (ch === '-' && next === '>') {
      this.pos += 2;
      this.column += 2;
      this.addToken('ARROW', '->');
      return true;
    }

    if (ch === '=' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken('EQ', '==');
      return true;
    }

    if (ch === '!' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken('NE', '!=');
      return true;
    }

    if (ch === '<' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken('LE', '<=');
      return true;
    }

    if (ch === '>' && next === '=') {
      this.pos += 2;
      this.column += 2;
      this.addToken('GE', '>=');
      return true;
    }

    const singleCharTokens = {
      '+': 'PLUS',
      '-': 'MINUS',
      '*': 'STAR',
      '/': 'SLASH',
      '=': 'ASSIGN',
      '<': 'LT',
      '>': 'GT',
      '(': 'LPAREN',
      ')': 'RPAREN',
      '[': 'LBRACKET',
      ']': 'RBRACKET',
      ':': 'COLON',
      ',': 'COMMA',
      '.': 'DOT',
    };

    if (singleCharTokens[ch]) {
      this.addToken(singleCharTokens[ch], ch);
      this.pos++;
      this.column++;
      return true;
    }

    return false;
  }

  skipWhitespaceOnLine() {
    while (this.pos < this.source.length && this.peek() === ' ') {
      this.pos++;
      this.column++;
    }
  }

  skipComment() {
    if (this.peek() === '#') {
      while (this.pos < this.source.length && !this.isNewline()) {
        this.pos++;
        this.column++;
      }
    }
  }

  consumeNewline() {
    if (this.peek() === '\r' && this.peekNext() === '\n') {
      this.pos += 2;
    } else {
      this.pos++;
    }
    this.line++;
    this.column = 1;
    this.addToken('NEWLINE', '\n');
  }

  isNewline() {
    return this.peek() === '\n' || (this.peek() === '\r' && this.peekNext() === '\n');
  }

  isComment() {
    return this.peek() === '#';
  }

  isDigit(ch) {
    return ch >= '0' && ch <= '9';
  }

  isLetter(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
  }

  peek() {
    return this.pos < this.source.length ? this.source[this.pos] : '\0';
  }

  peekNext() {
    return this.pos + 1 < this.source.length ? this.source[this.pos + 1] : '\0';
  }

  addToken(type, value) {
    this.tokens.push({
      type,
      value,
      line: this.line,
      column: this.column,
      raw: value ? String(value) : '',
    });
  }
}

// 간단한 Executor (파싱 없이 직접 실행)
function runV3Simple(source) {
  const output = [];

  // 간단한 상태 머신
  const lines = source.split('\n');
  const variables = {};

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    // INT x = 10
    const intMatch = trimmed.match(/^INT\s+(\w+)\s*=\s*(.+)$/);
    if (intMatch) {
      const [, name, expr] = intMatch;
      variables[name] = eval(expr.replace(/\w+/g, (match) => variables[match] ?? match));
      continue;
    }

    // STR x = "value"
    const strMatch = trimmed.match(/^STR\s+(\w+)\s*=\s*"(.*)"/);
    if (strMatch) {
      const [, name, value] = strMatch;
      variables[name] = value;
      continue;
    }

    // ARR x = [...]
    const arrMatch = trimmed.match(/^ARR\s+(\w+)\s*=\s*\[(.*)\]$/);
    if (arrMatch) {
      const [, name, elements] = arrMatch;
      variables[name] = elements.split(',').map((e) => {
        const num = parseInt(e.trim());
        return isNaN(num) ? e.trim() : num;
      });
      continue;
    }

    // ARR_SUM arr -> var
    const sumMatch = trimmed.match(/^ARR_SUM\s+(\w+)\s*->\s*(\w+)$/);
    if (sumMatch) {
      const [, arrName, varName] = sumMatch;
      const arr = variables[arrName];
      if (Array.isArray(arr)) {
        variables[varName] = arr.reduce((a, b) => a + b, 0);
      }
      continue;
    }

    // println(...)
    if (trimmed.startsWith('println(')) {
      const match = trimmed.match(/println\((.*)\)$/);
      if (match) {
        const expr = match[1];
        let value = expr;

        // 변수 대체
        for (const [name, val] of Object.entries(variables)) {
          const regex = new RegExp(`\\b${name}\\b`, 'g');
          if (typeof val === 'string') {
            value = value.replace(regex, `"${val}"`);
          } else if (Array.isArray(val)) {
            value = value.replace(regex, JSON.stringify(val));
          } else {
            value = value.replace(regex, val);
          }
        }

        try {
          const result = eval(value);
          output.push(String(result));
        } catch (e) {
          output.push(value);
        }
      }
      continue;
    }
  }

  return output.join('\n');
}

// 테스트
function test(filename, expected) {
  console.log(`\n테스트: ${filename}`);
  console.log('---');

  if (!fs.existsSync(filename)) {
    console.error(`❌ 파일 없음: ${filename}`);
    return;
  }

  const code = fs.readFileSync(filename, 'utf8');
  const result = runV3Simple(code);

  console.log('코드:');
  console.log(code);
  console.log('\n출력:');
  console.log(result);

  if (expected && result.includes(String(expected))) {
    console.log(`✅ PASS (기대값: ${expected})`);
  } else if (expected) {
    console.log(`❌ FAIL (기대값: ${expected})`);
  }
}

// 테스트 실행
console.log('═══════════════════════════════════════════');
console.log('V3 Language Test Runner');
console.log('═══════════════════════════════════════════');

test('test1.v3', 30);
test('test2.v3', 15);
test('test3.v3', 'big');
test('test4.v3', 5);

console.log('\n═══════════════════════════════════════════');
console.log('테스트 완료!');
console.log('═══════════════════════════════════════════');

