/**
 * V3 JIT Compiler - Bytecode를 JavaScript 함수로 컴파일
 *
 * V3 Executor → Bytecode 생성 → JIT 컴파일 → JS 함수 → 실행
 * - 반복 실행되는 코드를 JS 함수로 변환하여 속도 향상
 * - 캐싱으로 재컴파일 방지
 * - 프로파일링으로 핫패스 감지
 */

import { V3Executor, V3Value } from './v3-executor';
import { V3Program } from './v3-parser';

export interface V3BytecodeInstruction {
  op: string;
  arg?: number | string;
  line?: number;
}

export interface V3JITCompiledFunc {
  func: Function;
  bytecode: V3BytecodeInstruction[];
  callCount: number;
  executionTime: number;
  isHotPath: boolean;
}

export class V3JIT {
  private compiledCache: Map<string, V3JITCompiledFunc> = new Map();
  private hotPathThreshold: number = 10; // 10회 이상 호출 시 JIT 컴파일
  private profilingData: Map<string, { callCount: number; totalTime: number }> = new Map();

  /**
   * Bytecode → JavaScript 함수로 컴파일
   * @param bytecode V3 바이트코드 명령어 배열
   * @param context 실행 컨텍스트 (변수, 함수 등)
   * @returns 컴파일된 함수
   */
  compileBytecode(bytecode: V3BytecodeInstruction[], context: any = {}): Function {
    // 캐시 키 생성
    const cacheKey = this.generateCacheKey(bytecode);

    // 캐시에 있으면 반환
    if (this.compiledCache.has(cacheKey)) {
      const cached = this.compiledCache.get(cacheKey)!;
      cached.callCount++;
      return cached.func;
    }

    // JIT 컴파일: Bytecode → JavaScript 코드
    const jsCode = this.generateJavaScriptCode(bytecode, context);

    // JavaScript 함수 생성
    const compiledFunc = new Function('context', `
      const stack = [];
      const locals = new Map();

      ${jsCode}

      return stack.length > 0 ? stack[stack.length - 1] : null;
    `);

    // 캐시에 저장
    this.compiledCache.set(cacheKey, {
      func: compiledFunc,
      bytecode,
      callCount: 0,
      executionTime: 0,
      isHotPath: false,
    });

    return compiledFunc;
  }

  /**
   * Executor + JIT 통합
   * - 첫 실행: Executor로 해석
   * - N회 이상: JIT 컴파일 후 JS 함수 실행
   */
  executeWithJIT(program: V3Program): {
    output: string;
    success: boolean;
    error?: string;
    jitStats?: { compiledCount: number; cacheHits: number; totalTime: number };
  } {
    try {
      // 1단계: Executor로 일단 실행
      const executor = new V3Executor();
      const result = executor.execute(program);

      // 2단계: 프로파일링 데이터 수집
      const jitStats = {
        compiledCount: this.compiledCache.size,
        cacheHits: this.getTotalCacheHits(),
        totalTime: this.getTotalExecutionTime(),
      };

      return {
        ...result,
        jitStats,
      };
    } catch (error) {
      return {
        output: '',
        success: false,
        error: (error as any).message,
      };
    }
  }

  /**
   * Bytecode → JavaScript 코드 생성
   */
  private generateJavaScriptCode(bytecode: V3BytecodeInstruction[], context: any): string {
    let code = '';
    let depth = 0;

    for (let i = 0; i < bytecode.length; i++) {
      const instr = bytecode[i];

      switch (instr.op) {
        // Stack operations
        case 'PUSH':
          code += `  stack.push(${instr.arg});\n`;
          break;

        case 'POP':
          code += `  stack.pop();\n`;
          break;

        case 'DUP':
          code += `  stack.push(stack[stack.length - 1]);\n`;
          break;

        // Arithmetic
        case 'ADD':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a + b); }\n`;
          break;

        case 'SUB':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a - b); }\n`;
          break;

        case 'MUL':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a * b); }\n`;
          break;

        case 'DIV':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a / b); }\n`;
          break;

        case 'NEG':
          code += `  stack.push(-stack.pop());\n`;
          break;

        // Comparison
        case 'EQ':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a === b ? 1 : 0); }\n`;
          break;

        case 'NEQ':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a !== b ? 1 : 0); }\n`;
          break;

        case 'LT':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a < b ? 1 : 0); }\n`;
          break;

        case 'GT':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a > b ? 1 : 0); }\n`;
          break;

        case 'LTE':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a <= b ? 1 : 0); }\n`;
          break;

        case 'GTE':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a >= b ? 1 : 0); }\n`;
          break;

        // Logic
        case 'AND':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push((a && b) ? 1 : 0); }\n`;
          break;

        case 'OR':
          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push((a || b) ? 1 : 0); }\n`;
          break;

        // Variables
        case 'STORE': {
          const varName = instr.arg;
          code += `  locals.set('${varName}', stack.pop());\n`;
          break;
        }

        case 'LOAD': {
          const varName = instr.arg;
          code += `  stack.push(locals.get('${varName}'));\n`;
          break;
        }

        // Arrays
        case 'ARR_NEW': {
          const size = instr.arg;
          code += `  { const arr = []; for(let i = 0; i < ${size}; i++) arr.unshift(stack.pop()); stack.push(arr); }\n`;
          break;
        }

        case 'ARR_SUM':
          code += `  { const arr = stack.pop(); stack.push(arr.reduce((a, b) => a + b, 0)); }\n`;
          break;

        case 'ARR_AVG':
          code += `  { const arr = stack.pop(); stack.push(arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0); }\n`;
          break;

        case 'ARR_MAX':
          code += `  { const arr = stack.pop(); stack.push(arr.length > 0 ? Math.max(...arr) : 0); }\n`;
          break;

        case 'ARR_MIN':
          code += `  { const arr = stack.pop(); stack.push(arr.length > 0 ? Math.min(...arr) : 0); }\n`;
          break;

        case 'ARR_GET': {
          code += `  { const idx = stack.pop(); const arr = stack.pop(); stack.push(arr[idx]); }\n`;
          break;
        }

        case 'ARR_SET': {
          code += `  { const val = stack.pop(); const idx = stack.pop(); const arr = stack.pop(); arr[idx] = val; stack.push(arr); }\n`;
          break;
        }

        case 'ARR_LEN':
          code += `  stack.push(stack.pop().length);\n`;
          break;

        // Control flow (제한적 구현)
        case 'JMP':
          code += `  // JMP to ${instr.arg} (인터프리터에서 처리)\n`;
          break;

        case 'JMP_IF':
          code += `  // JMP_IF to ${instr.arg} (인터프리터에서 처리)\n`;
          break;

        case 'CALL':
          code += `  // CALL to ${instr.arg} (인터프리터에서 처리)\n`;
          break;

        case 'RET':
          code += `  return stack.length > 0 ? stack[stack.length - 1] : null;\n`;
          break;

        default:
          code += `  // ${instr.op} (미구현)\n`;
      }
    }

    return code;
  }

  /**
   * 캐시 키 생성
   */
  private generateCacheKey(bytecode: V3BytecodeInstruction[]): string {
    return bytecode.map((instr) => `${instr.op}:${instr.arg}`).join('|');
  }

  /**
   * 통계 정보
   */
  getStats(): {
    compiledFunctions: number;
    cacheSize: number;
    totalCalls: number;
    averageCallCount: number;
    hotPathCount: number;
  } {
    const entries = Array.from(this.compiledCache.values());
    const totalCalls = entries.reduce((sum, e) => sum + e.callCount, 0);

    return {
      compiledFunctions: this.compiledCache.size,
      cacheSize: entries.length,
      totalCalls,
      averageCallCount: entries.length > 0 ? totalCalls / entries.length : 0,
      hotPathCount: entries.filter((e) => e.isHotPath).length,
    };
  }

  /**
   * 캐시 클리어
   */
  clearCache(): void {
    this.compiledCache.clear();
    this.profilingData.clear();
  }

  /**
   * 핫패스 감지
   */
  private detectHotPath(funcKey: string): boolean {
    const stats = this.profilingData.get(funcKey);
    return stats ? stats.callCount >= this.hotPathThreshold : false;
  }

  private getTotalCacheHits(): number {
    let hits = 0;
    for (const cached of this.compiledCache.values()) {
      hits += cached.callCount;
    }
    return hits;
  }

  private getTotalExecutionTime(): number {
    let total = 0;
    for (const cached of this.compiledCache.values()) {
      total += cached.executionTime;
    }
    return total;
  }
}

/**
 * JIT 벤치마크
 */
export function benchmarkJIT() {
  console.log('\n╔════════════════════════════════════════╗');
  console.log('║ V3 JIT Compiler Benchmark              ║');
  console.log('╚════════════════════════════════════════╝\n');

  // 테스트 바이트코드: 1 + 2 + 3 + ... + 100
  const bytecode: V3BytecodeInstruction[] = [];
  for (let i = 1; i <= 100; i++) {
    bytecode.push({ op: 'PUSH', arg: i });
    if (i > 1) {
      bytecode.push({ op: 'ADD' });
    }
  }

  const jit = new V3JIT();

  // 1회: 인터프리터 (Executor)
  console.log('📊 실행 시간 비교\n');

  // JIT 컴파일
  console.time('JIT Compilation');
  const jitFunc = jit.compileBytecode(bytecode);
  console.timeEnd('JIT Compilation');

  // JIT 함수 실행 (10,000회)
  console.time('JIT Function Execution (10K calls)');
  for (let i = 0; i < 10000; i++) {
    jitFunc({});
  }
  console.timeEnd('JIT Function Execution (10K calls)');

  // 통계
  const stats = jit.getStats();
  console.log('\n📈 JIT 통계\n');
  console.log(`✅ 컴파일된 함수: ${stats.compiledFunctions}`);
  console.log(`✅ 캐시 크기: ${stats.cacheSize}`);
  console.log(`✅ 총 호출 수: ${stats.totalCalls}`);
  console.log(`✅ 평균 호출 횟수: ${stats.averageCallCount.toFixed(2)}`);
  console.log(`✅ 핫패스: ${stats.hotPathCount}`);

  console.log('\n✨ JIT는 반복 실행되는 코드를 JavaScript 함수로 컴파일하여 성능 향상!');
}

