/**
 * AI VM (Virtual Machine)
 *
 * AIInst를 직접 실행하고 성능을 자동으로 측정
 */

import { AIOp, AIInst, AIProgram, AIIntent } from './ai-ir';

/**
 * 실행 메트릭
 */
export interface AIMetrics {
  cycles: number;
  time: number;
  stackMax: number;
  ops: Map<string, number>; // 연산별 카운트
}

/**
 * 실행 결과
 */
export interface AIResult {
  ok: boolean;
  value?: any;
  error?: string;
  metrics: AIMetrics;
}

/**
 * AI 가상 머신
 */
export class AIVM {
  private stack: any[] = [];
  private vars: Map<string, any> = new Map();
  private cycles = 0;
  private stackMax = 0;
  private opCounts: Map<string, number> = new Map();

  /**
   * 실행
   */
  run(program: AIProgram | AIIntent, variables?: Record<string, any>): AIResult {
    this.reset();

    // 변수 초기화
    if (variables) {
      for (const [k, v] of Object.entries(variables)) {
        this.vars.set(k, v);
      }
    }

    const start = Date.now();

    try {
      // AIIntent인 경우 body, AIProgram인 경우 functions[0].body
      let body: AIInst[] = [];
      if ('body' in program) {
        body = program.body;
      } else if ('functions' in program && program.functions.length > 0) {
        body = program.functions[0].body;
      }
      this.execute(body);

      const value = this.stack.length > 0 ? this.stack[0] : undefined;
      return {
        ok: true,
        value,
        metrics: {
          cycles: this.cycles,
          time: Date.now() - start,
          stackMax: this.stackMax,
          ops: this.opCounts,
        },
      };
    } catch (e: any) {
      return {
        ok: false,
        error: e.message,
        metrics: {
          cycles: this.cycles,
          time: Date.now() - start,
          stackMax: this.stackMax,
          ops: this.opCounts,
        },
      };
    }
  }

  /**
   * 명령 시퀀스 실행
   */
  private execute(instructions: AIInst[]): void {
    for (const inst of instructions) {
      this.executeInst(inst);

      if (this.cycles > 10000000) throw new Error('Cycle limit exceeded');
    }
  }

  /**
   * 단일 명령 실행
   */
  private executeInst(inst: AIInst): void {
    this.cycles++;
    this.opCounts.set(inst.op, (this.opCounts.get(inst.op) || 0) + 1);

    switch (inst.op) {
