        const top = this.stack[this.stack.length - 1];
        this.stack.push(top);
        break;
      }
      case AIOp.SWAP: {
        const b = this.stack.pop();
        const a = this.stack.pop();
        this.stack.push(b);
        this.stack.push(a);
        break;
      }

