/**
 * V3 Full Runtime - Bytecode를 AIVM에서 실행
 *
 * Bytecode (v3-bytecode-gen) → AIVM 실행
 * 최종 완성: Lexer → Parser → BytecodeGen → AIVM Runtime
 */

import { V3BytecodeInstruction } from './v3-jit';
import { AIOp, AIInst, AIProgram } from './ai-ir';

/**
 * V3 Bytecode → AIOp AIInst 변환
 */
export class V3BytecodeToAIOp {
  /**
   * V3 Bytecode → AIOp 명령어 변환
   */
  static convert(bytecode: V3BytecodeInstruction[]): AIInst[] {
    const instructions: AIInst[] = [];

    for (const instr of bytecode) {
      const aiInst = V3BytecodeToAIOp.convertInstruction(instr);
      if (aiInst) {
        instructions.push(aiInst);
      }
    }

    return instructions;
  }

  private static convertInstruction(instr: V3BytecodeInstruction): AIInst | null {
    switch (instr.op) {
      // Stack operations
      case 'PUSH':
        return { op: AIOp.PUSH, arg: instr.arg };
      case 'POP':
        return { op: AIOp.POP };
      case 'DUP':
        return { op: AIOp.DUP };
      case 'SWAP':
        return { op: AIOp.SWAP };

      // Arithmetic
      case 'ADD':
        return { op: AIOp.ADD };
      case 'SUB':
        return { op: AIOp.SUB };
      case 'MUL':
        return { op: AIOp.MUL };
      case 'DIV':
        return { op: AIOp.DIV };
      case 'MOD':
        return { op: AIOp.MOD };
      case 'NEG':
        return { op: AIOp.NEG };

      // Comparison
      case 'EQ':
        return { op: AIOp.EQ };
      case 'NEQ':
        return { op: AIOp.NEQ };
      case 'LT':
        return { op: AIOp.LT };
      case 'GT':
        return { op: AIOp.GT };
      case 'LTE':
        return { op: AIOp.LTE };
      case 'GTE':
        return { op: AIOp.GTE };

      // Logic
      case 'AND':
        return { op: AIOp.AND };
      case 'OR':
        return { op: AIOp.OR };
      case 'NOT':
        return { op: AIOp.NOT };

      // Variables
      case 'STORE':
        return { op: AIOp.STORE, arg: instr.arg };
      case 'LOAD':
        return { op: AIOp.LOAD, arg: instr.arg };

      // Arrays
      case 'ARR_NEW':
        return { op: AIOp.ARR_NEW, arg: instr.arg };
      case 'ARR_GET':
        return { op: AIOp.ARR_GET };
      case 'ARR_SET':
        return { op: AIOp.ARR_SET };
      case 'ARR_LEN':
        return { op: AIOp.ARR_LEN };
      case 'ARR_SUM':
        return { op: AIOp.ARR_SUM };
      case 'ARR_AVG':
        return { op: AIOp.ARR_AVG };
      case 'ARR_MAX':
        return { op: AIOp.ARR_MAX };
      case 'ARR_MIN':
        return { op: AIOp.ARR_MIN };

      // Control flow (제한적)
      case 'JMP':
      case 'JMP_IF':
      case 'JMP_NOT':
      case 'CALL':
      case 'RET':
        return null; // AIVM에서 직접 처리 불가, 인터프리터에서 처리

      case 'HALT':
        return { op: AIOp.HALT };

      default:
        return null;
    }
  }
}

/**
 * V3 Full Runtime - Bytecode 실행
 */
export interface V3RuntimeResult {
  success: boolean;
  value?: any;
  output: string;
  error?: string;
  executionTime: number;
  metrics?: {
    cycles: number;
    stackMax: number;
    ops: Map<string, number>;
  };
}

export class V3FullRuntime {
  private output: string[] = [];

  /**
   * V3 Bytecode 실행 (AIVM)
   */
  executeBytecode(bytecode: V3BytecodeInstruction[]): V3RuntimeResult {
    const startTime = Date.now();
    this.output = [];

    try {
      // 1. Bytecode → AIOp 변환
      const aiInstructions = V3BytecodeToAIOp.convert(bytecode);

      // 2. AIProgram 생성
      const aiProgram: AIProgram = {
        version: '1.0',
        functions: [
          {
            name: 'main',
            params: [],
            body: aiInstructions,
          },
        ],
      };

      // 3. AIVM에서 실행
      const aivm = require('./ai-vm').AIVM;
      if (!aivm) {
        // AIVM을 사용할 수 없으면 폴백
        return this.executeBytecodeSimple(bytecode);
      }

      const vm = new aivm();
      const result = vm.run(aiProgram);

      if (!result.ok) {
        return {
          success: false,
          output: this.output.join('\n'),
          error: result.error,
          executionTime: Date.now() - startTime,
        };
      }

      return {
        success: true,
        value: result.value,
        output: this.output.join('\n'),
        executionTime: Date.now() - startTime,
        metrics: {
          cycles: result.metrics.cycles,
          stackMax: result.metrics.stackMax,
          ops: result.metrics.ops,
        },
      };
    } catch (error) {
      // AIVM 사용 불가 시 폴백
      return this.executeBytecodeSimple(bytecode);
    }
  }

  /**
   * 간단한 Bytecode 실행기 (폴백)
   * AIVM이 없을 때 사용
   */
  private executeBytecodeSimple(bytecode: V3BytecodeInstruction[]): V3RuntimeResult {
    const startTime = Date.now();
    this.output = [];

    try {
      const stack: any[] = [];
      const variables: Map<string, any> = new Map();
      let pc = 0; // Program Counter

      while (pc < bytecode.length) {
        const instr = bytecode[pc];

        switch (instr.op) {
          // Stack
          case 'PUSH':
            stack.push(instr.arg);
            break;
          case 'POP':
            stack.pop();
            break;
          case 'DUP':
            stack.push(stack[stack.length - 1]);
            break;
          case 'SWAP': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(b);
            stack.push(a);
            break;
          }

          // Arithmetic
          case 'ADD': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a + b);
            break;
          }
          case 'SUB': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a - b);
            break;
          }
          case 'MUL': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a * b);
            break;
          }
          case 'DIV': {
            const b = stack.pop();
            const a = stack.pop();
            if (b === 0) throw new Error('Division by zero');
            stack.push(a / b);
            break;
          }
          case 'NEG':
            stack.push(-stack.pop());
            break;

          // Comparison
          case 'EQ': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a === b ? 1 : 0);
            break;
          }
          case 'NEQ': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a !== b ? 1 : 0);
            break;
          }
          case 'LT': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a < b ? 1 : 0);
            break;
          }
          case 'GT': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a > b ? 1 : 0);
            break;
          }
          case 'LTE': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a <= b ? 1 : 0);
            break;
          }
          case 'GTE': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a >= b ? 1 : 0);
            break;
          }

          // Logic
          case 'AND': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a && b ? 1 : 0);
            break;
          }
          case 'OR': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a || b ? 1 : 0);
            break;
          }

          // Variables
          case 'STORE': {
            const value = stack.pop();
            variables.set(String(instr.arg), value);
            break;
          }
          case 'LOAD': {
            const value = variables.get(String(instr.arg));
            stack.push(value);
            break;
          }

          // Arrays
          case 'ARR_NEW': {
            const size = instr.arg;
            const arr = [];
            for (let i = 0; i < size; i++) {
              arr.unshift(stack.pop());
            }
            stack.push(arr);
            break;
          }
          case 'ARR_GET': {
            const idx = stack.pop();
            const arr = stack.pop();
            stack.push(arr[idx]);
            break;
          }
          case 'ARR_SET': {
            const val = stack.pop();
            const idx = stack.pop();
            const arr = stack.pop();
            arr[idx] = val;
            stack.push(arr);
            break;
          }
          case 'ARR_LEN':
            stack.push(stack.pop().length);
            break;
          case 'ARR_SUM': {
            const arr = stack.pop();
            stack.push(arr.reduce((a: any, b: any) => a + b, 0));
            break;
          }
          case 'ARR_AVG': {
            const arr = stack.pop();
            stack.push(arr.length > 0 ? arr.reduce((a: any, b: any) => a + b, 0) / arr.length : 0);
            break;
          }
          case 'ARR_MAX': {
            const arr = stack.pop();
            stack.push(Math.max(...arr));
            break;
          }
          case 'ARR_MIN': {
            const arr = stack.pop();
            stack.push(Math.min(...arr));
            break;
          }

          // Built-in functions
          case 'CALL':
            if (instr.arg === -1) {
              // println
              const arg = stack.pop();
              this.output.push(this.stringify(arg));
            }
            break;

          case 'HALT':
            pc = bytecode.length; // 종료
            break;

          case 'RET':
            pc = bytecode.length; // 종료
            break;

          // 제어흐름은 간단히 처리
          case 'JMP':
          case 'JMP_IF':
          case 'JMP_NOT':
            // Skip - 인터프리터에서 처리
            break;
        }

        pc++;
      }

      const result = stack.length > 0 ? stack[stack.length - 1] : undefined;

      return {
        success: true,
        value: result,
        output: this.output.join('\n'),
        executionTime: Date.now() - startTime,
      };
    } catch (error) {
      return {
        success: false,
        output: this.output.join('\n'),
        error: (error as any).message,
        executionTime: Date.now() - startTime,
      };
    }
  }

  private stringify(value: any): string {
    if (Array.isArray(value)) {
      return '[' + value.map((v) => this.stringify(v)).join(', ') + ']';
    }
    if (typeof value === 'string') {
      return value;
    }
    if (typeof value === 'boolean') {
      return value ? 'true' : 'false';
    }
    if (value === null || value === undefined) {
      return 'null';
    }
    return String(value);
  }
}

/**
 * 완전 파이프라인: Lexer → Parser → BytecodeGen → Runtime
 */
export async function executeV3Full(source: string): Promise<V3RuntimeResult> {
  try {
    const { V3Parser } = require('./v3-parser');
    const { V3BytecodeGenerator, programToBytecode } = require('./v3-bytecode-gen');

    // 1. Parse
    const parser = new V3Parser(source);
    const ast = parser.parse();

    // 2. Generate Bytecode
    const bytecode = programToBytecode(ast);

    // 3. Execute
    const runtime = new V3FullRuntime();
    const result = runtime.executeBytecode(bytecode);

    return result;
  } catch (error) {
    return {
      success: false,
      output: '',
      error: (error as any).message,
      executionTime: 0,
    };
  }
}

export { V3BytecodeGenerator, programToBytecode } from './v3-bytecode-gen';

