          case 'DUP':
            stack.push(stack[stack.length - 1]);
            break;
          case 'SWAP': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(b);
            stack.push(a);
            break;
          }

          // Arithmetic
          case 'ADD': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a + b);
            break;
          }
          case 'SUB': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a - b);
            break;
          }
          case 'MUL': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a * b);
            break;
          }
          case 'DIV': {
            const b = stack.pop();
            const a = stack.pop();
            if (b === 0) throw new Error('Division by zero');
            stack.push(a / b);
            break;
          }
          case 'NEG':
            stack.push(-stack.pop());
            break;

          // Comparison
          case 'EQ': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a === b ? 1 : 0);
            break;
          }
          case 'NEQ': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a !== b ? 1 : 0);
            break;
          }
          case 'LT': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a < b ? 1 : 0);
            break;
          }
          case 'GT': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a > b ? 1 : 0);
            break;
          }
          case 'LTE': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a <= b ? 1 : 0);
            break;
          }
          case 'GTE': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a >= b ? 1 : 0);
            break;
          }

          // Logic
          case 'AND': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a && b ? 1 : 0);
            break;
          }
          case 'OR': {
            const b = stack.pop();
            const a = stack.pop();
            stack.push(a || b ? 1 : 0);
            break;
          }

          // Variables
          case 'STORE': {
            const value = stack.pop();
            variables.set(String(instr.arg), value);
            break;
          }
          case 'LOAD': {
            const value = variables.get(String(instr.arg));
            stack.push(value);
            break;
          }

          // Arrays
          case 'ARR_NEW': {
            const size = instr.arg;
            const arr = [];
            for (let i = 0; i < size; i++) {
              arr.unshift(stack.pop());
            }
            stack.push(arr);
            break;
          }
          case 'ARR_GET': {
            const idx = stack.pop();
            const arr = stack.pop();
            stack.push(arr[idx]);
            break;
          }
          case 'ARR_SET': {
            const val = stack.pop();
            const idx = stack.pop();
            const arr = stack.pop();
            arr[idx] = val;
            stack.push(arr);
            break;
          }
          case 'ARR_LEN':
            stack.push(stack.pop().length);
            break;
          case 'ARR_SUM': {
            const arr = stack.pop();
            stack.push(arr.reduce((a: any, b: any) => a + b, 0));
            break;
          }
          case 'ARR_AVG': {
            const arr = stack.pop();
            stack.push(arr.length > 0 ? arr.reduce((a: any, b: any) => a + b, 0) / arr.length : 0);
            break;
          }
          case 'ARR_MAX': {
            const arr = stack.pop();
            stack.push(Math.max(...arr));
            break;
          }
          case 'ARR_MIN': {
            const arr = stack.pop();
            stack.push(Math.min(...arr));
            break;
          }

          // Built-in functions
          case 'CALL':
            if (instr.arg === -1) {
              // println
              const arg = stack.pop();
              this.output.push(this.stringify(arg));
            }
            break;

          case 'HALT':
            pc = bytecode.length; // 종료
            break;

          case 'RET':
            pc = bytecode.length; // 종료
            break;

          // 제어흐름은 간단히 처리
          case 'JMP':
          case 'JMP_IF':
          case 'JMP_NOT':
            // Skip - 인터프리터에서 처리
            break;
        }

        pc++;
      }

      const result = stack.length > 0 ? stack[stack.length - 1] : undefined;

      return {
        success: true,
        value: result,
        output: this.output.join('\n'),
        executionTime: Date.now() - startTime,
      };
    } catch (error) {
      return {
        success: false,
        output: this.output.join('\n'),
        error: (error as any).message,
        executionTime: Date.now() - startTime,
      };
    }
  }

  private stringify(value: any): string {
    if (Array.isArray(value)) {
      return '[' + value.map((v) => this.stringify(v)).join(', ') + ']';
    }
    if (typeof value === 'string') {
      return value;
    }
    if (typeof value === 'boolean') {
      return value ? 'true' : 'false';
    }
    if (value === null || value === undefined) {
      return 'null';
    }
    return String(value);
  }
}

/**
 * 완전 파이프라인: Lexer → Parser → BytecodeGen → Runtime
 */
export async function executeV3Full(source: string): Promise<V3RuntimeResult> {
  try {
    const { V3Parser } = require('./v3-parser');
    const { V3BytecodeGenerator, programToBytecode } = require('./v3-bytecode-gen');

    // 1. Parse
    const parser = new V3Parser(source);
    const ast = parser.parse();

    // 2. Generate Bytecode
    const bytecode = programToBytecode(ast);

    // 3. Execute
    const runtime = new V3FullRuntime();
    const result = runtime.executeBytecode(bytecode);

    return result;
  } catch (error) {
    return {
      success: false,
      output: '',
      error: (error as any).message,
      executionTime: 0,
    };
  }
}

