/**
 * V3 Full Pipeline Test
 * Lexer → Parser → BytecodeGen → Runtime
 */

const fs = require('fs');

// Lexer (간단한 버전)
class SimpleLexer {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
  }

  tokenize() {
    while (this.pos < this.source.length) {
      this.skipWhitespace();

      if (this.isNewline()) {
        this.pos++;
        this.line++;
        this.column = 1;
        continue;
      }

      if (this.isComment()) {
        this.skipComment();
        continue;
      }

      const ch = this.peek();

      if (ch === '"') {
        this.consumeString();
        continue;
      }

      if (this.isDigit(ch)) {
        this.consumeNumber();
        continue;
      }

      if (this.isLetter(ch) || ch === '_') {
        this.consumeIdentifier();
        continue;
      }

      this.consumeOperator();
    }

    this.tokens.push({ type: 'EOF', value: null });
    return this.tokens;
  }

  skipWhitespace() {
    while (this.pos < this.source.length && this.peek() === ' ') {
      this.pos++;
      this.column++;
    }
  }

  isNewline() {
    return this.peek() === '\n';
  }

  isComment() {
    return this.peek() === '#';
  }

  isDigit(ch) {
    return ch >= '0' && ch <= '9';
  }

  isLetter(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
  }

  peek() {
    return this.pos < this.source.length ? this.source[this.pos] : '\0';
  }

  peekNext() {
    return this.pos + 1 < this.source.length ? this.source[this.pos + 1] : '\0';
  }

  consumeString() {
    this.pos++; // skip "
    let value = '';
    while (this.peek() !== '"' && this.pos < this.source.length) {
      value += this.peek();
      this.pos++;
    }
    this.pos++; // skip closing "
    this.tokens.push({ type: 'STRING', value });
  }

  consumeNumber() {
    let value = '';
    while (this.isDigit(this.peek())) {
      value += this.peek();
      this.pos++;
    }
    this.tokens.push({ type: 'NUMBER', value: parseInt(value) });
  }

  consumeIdentifier() {
    let value = '';
    while (this.isLetter(this.peek()) || this.isDigit(this.peek()) || this.peek() === '_') {
      value += this.peek();
      this.pos++;
    }

    const keywords = ['INT', 'ARR', 'STR', 'IF', 'FOR', 'IN', 'FUNC', 'RETURN', 'CALL', 'TRUE', 'FALSE', 'ARR_SUM', 'ARR_AVG'];
    if (keywords.includes(value)) {
      this.tokens.push({ type: 'KEYWORD', value });
    } else {
      this.tokens.push({ type: 'IDENTIFIER', value });
    }
  }

  consumeOperator() {
    const ch = this.peek();
    const next = this.peekNext();

    if (ch === '=' && next === '=') {
      this.tokens.push({ type: 'OP', value: '==' });
      this.pos += 2;
    } else if (ch === '!' && next === '=') {
      this.tokens.push({ type: 'OP', value: '!=' });
      this.pos += 2;
    } else if (ch === '-' && next === '>') {
      this.tokens.push({ type: 'ARROW', value: '->' });
      this.pos += 2;
    } else if (ch === '<' && next === '=') {
      this.tokens.push({ type: 'OP', value: '<=' });
      this.pos += 2;
    } else if (ch === '>' && next === '=') {
      this.tokens.push({ type: 'OP', value: '>=' });
      this.pos += 2;
    } else {
      const opChars = '+-*/<>=()[],:';
      if (opChars.includes(ch)) {
        this.tokens.push({ type: 'OP', value: ch });
        this.pos++;
      } else {
        this.pos++;
      }
    }
  }

  skipComment() {
    while (this.peek() !== '\n' && this.pos < this.source.length) {
      this.pos++;
    }
  }
}

// Bytecode Generator (간단한 버전)
class SimpleBytecodeGen {
  generate(source) {
    const lexer = new SimpleLexer(source);
    const tokens = lexer.tokenize();

    const bytecode = [];
    const variables = new Map();
    let varAddr = 0;

    const lines = source.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;

      // INT x = 10
      const intMatch = trimmed.match(/^INT\s+(\w+)\s*=\s*(.+)$/);
      if (intMatch) {
        const [, name, expr] = intMatch;
        const addr = varAddr++;
        variables.set(name, addr);

        // expr를 PUSH로 변환
        const numMatch = expr.match(/^\d+$/);
        if (numMatch) {
          bytecode.push({ op: 'PUSH', arg: parseInt(expr) });
        } else {
          // 변수 참조
          const varAddr = variables.get(expr);
          if (varAddr !== undefined) {
            bytecode.push({ op: 'LOAD', arg: varAddr });
          } else {
            bytecode.push({ op: 'PUSH', arg: expr });
          }
        }

        bytecode.push({ op: 'STORE', arg: addr });
        continue;
      }

      // ARR nums = [...]
      const arrMatch = trimmed.match(/^ARR\s+(\w+)\s*=\s*\[(.*)\]$/);
      if (arrMatch) {
        const [, name, elements] = arrMatch;
        const addr = varAddr++;
        variables.set(name, addr);

        const nums = elements.split(',').map((e) => parseInt(e.trim()));
        for (const num of nums) {
          bytecode.push({ op: 'PUSH', arg: num });
        }
        bytecode.push({ op: 'ARR_NEW', arg: nums.length });
        bytecode.push({ op: 'STORE', arg: addr });
        continue;
      }

      // ARR_SUM arr -> var
      const sumMatch = trimmed.match(/^ARR_SUM\s+(\w+)\s*->\s*(\w+)$/);
      if (sumMatch) {
        const [, arrName, varName] = sumMatch;
        const arrAddr = variables.get(arrName);
        const resultAddr = varAddr++;
        variables.set(varName, resultAddr);

        bytecode.push({ op: 'LOAD', arg: arrAddr });
        bytecode.push({ op: 'ARR_SUM' });
        bytecode.push({ op: 'STORE', arg: resultAddr });
        continue;
      }

      // ARR_AVG arr -> var
      const avgMatch = trimmed.match(/^ARR_AVG\s+(\w+)\s*->\s*(\w+)$/);
      if (avgMatch) {
        const [, arrName, varName] = avgMatch;
        const arrAddr = variables.get(arrName);
        const resultAddr = varAddr++;
        variables.set(varName, resultAddr);

        bytecode.push({ op: 'LOAD', arg: arrAddr });
        bytecode.push({ op: 'ARR_AVG' });
        bytecode.push({ op: 'STORE', arg: resultAddr });
        continue;
      }

      // println(...)
      if (trimmed.startsWith('println(')) {
        const match = trimmed.match(/println\((.*)\)$/);
        if (match) {
          const expr = match[1];
          // 변수 또는 리터럴
          const varAddr = variables.get(expr);
          if (varAddr !== undefined) {
            bytecode.push({ op: 'LOAD', arg: varAddr });
          } else {
            const num = parseInt(expr);
            if (!isNaN(num)) {
              bytecode.push({ op: 'PUSH', arg: num });
            } else {
              bytecode.push({ op: 'PUSH', arg: expr });
            }
          }
          bytecode.push({ op: 'CALL', arg: -1 });
        }
        continue;
      }
    }

    bytecode.push({ op: 'HALT' });
    return { bytecode, variables };
  }
}

// Runtime (실행)
class SimpleRuntime {
  execute(bytecode) {
    const stack = [];
    const variables = new Map();
    const output = [];

    for (const instr of bytecode) {
      switch (instr.op) {
        case 'PUSH':
          stack.push(instr.arg);
          break;

        case 'POP':
          stack.pop();
          break;

        case 'LOAD':
          stack.push(variables.get(instr.arg));
          break;

        case 'STORE':
          variables.set(instr.arg, stack.pop());
          break;

        case 'ADD': {
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a + b);
          break;
        }

        case 'SUB': {
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a - b);
          break;
        }

        case 'MUL': {
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a * b);
          break;
        }

        case 'ARR_NEW': {
          const size = instr.arg;
          const arr = [];
          for (let i = 0; i < size; i++) {
            arr.unshift(stack.pop());
          }
          stack.push(arr);
          break;
        }

        case 'ARR_SUM': {
          const arr = stack.pop();
          stack.push(arr.reduce((a, b) => a + b, 0));
          break;
        }

        case 'ARR_AVG': {
          const arr = stack.pop();
          stack.push(arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0);
          break;
        }

        case 'CALL':
          if (instr.arg === -1) {
            // println
            const arg = stack.pop();
            output.push(String(arg));
          }
          break;

        case 'HALT':
          break;
      }
    }

    return {
      output: output.join('\n'),
      stack: stack.length > 0 ? stack[stack.length - 1] : null,
    };
  }
}

// 테스트 실행
console.log('\n╔════════════════════════════════════════╗');
console.log('║ V3 Full Pipeline Test (4단계)          ║');
console.log('║ Lexer → Parser → BytecodeGen → Runtime ║');
console.log('╚════════════════════════════════════════╝\n');

function test(name, code, expected) {
  console.log(`\n📍 테스트: ${name}`);
  console.log('─'.repeat(40));
  console.log('코드:');
  console.log(code);
