      const sumMatch = trimmed.match(/^ARR_SUM\s+(\w+)\s*->\s*(\w+)$/);
      if (sumMatch) {
        const [, arrName, varName] = sumMatch;
        const arrAddr = variables.get(arrName);
        const resultAddr = varAddr++;
        variables.set(varName, resultAddr);

        bytecode.push({ op: 'LOAD', arg: arrAddr });
        bytecode.push({ op: 'ARR_SUM' });
        bytecode.push({ op: 'STORE', arg: resultAddr });
        continue;
      }

      // ARR_AVG arr -> var
      const avgMatch = trimmed.match(/^ARR_AVG\s+(\w+)\s*->\s*(\w+)$/);
      if (avgMatch) {
        const [, arrName, varName] = avgMatch;
        const arrAddr = variables.get(arrName);
        const resultAddr = varAddr++;
        variables.set(varName, resultAddr);

        bytecode.push({ op: 'LOAD', arg: arrAddr });
        bytecode.push({ op: 'ARR_AVG' });
        bytecode.push({ op: 'STORE', arg: resultAddr });
        continue;
      }

      // println(...)
      if (trimmed.startsWith('println(')) {
        const match = trimmed.match(/println\((.*)\)$/);
        if (match) {
          const expr = match[1];
          // 변수 또는 리터럴
          const varAddr = variables.get(expr);
          if (varAddr !== undefined) {
            bytecode.push({ op: 'LOAD', arg: varAddr });
          } else {
            const num = parseInt(expr);
            if (!isNaN(num)) {
              bytecode.push({ op: 'PUSH', arg: num });
            } else {
              bytecode.push({ op: 'PUSH', arg: expr });
            }
          }
          bytecode.push({ op: 'CALL', arg: -1 });
        }
        continue;
      }
    }

    bytecode.push({ op: 'HALT' });
    return { bytecode, variables };
  }
}

// Runtime (실행)
class SimpleRuntime {
  execute(bytecode) {
    const stack = [];
    const variables = new Map();
    const output = [];

    for (const instr of bytecode) {
      switch (instr.op) {
        case 'PUSH':
          stack.push(instr.arg);
          break;

        case 'POP':
          stack.pop();
          break;

        case 'LOAD':
          stack.push(variables.get(instr.arg));
          break;

        case 'STORE':
          variables.set(instr.arg, stack.pop());
          break;

        case 'ADD': {
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a + b);
          break;
        }

        case 'SUB': {
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a - b);
          break;
        }

        case 'MUL': {
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a * b);
          break;
        }

        case 'ARR_NEW': {
          const size = instr.arg;
          const arr = [];
          for (let i = 0; i < size; i++) {
            arr.unshift(stack.pop());
          }
          stack.push(arr);
          break;
        }

        case 'ARR_SUM': {
          const arr = stack.pop();
          stack.push(arr.reduce((a, b) => a + b, 0));
          break;
        }

        case 'ARR_AVG': {
          const arr = stack.pop();
          stack.push(arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0);
          break;
        }

        case 'CALL':
          if (instr.arg === -1) {
            // println
            const arg = stack.pop();
            output.push(String(arg));
          }
          break;

        case 'HALT':
          break;
      }
    }

    return {
      output: output.join('\n'),
      stack: stack.length > 0 ? stack[stack.length - 1] : null,
    };
  }
}

// 테스트 실행
console.log('\n╔════════════════════════════════════════╗');
console.log('║ V3 Full Pipeline Test (4단계)          ║');
console.log('║ Lexer → Parser → BytecodeGen → Runtime ║');
console.log('╚════════════════════════════════════════╝\n');

function test(name, code, expected) {
  console.log(`\n📍 테스트: ${name}`);
  console.log('─'.repeat(40));
  console.log('코드:');
  console.log(code);
  console.log('');

  try {
    const gen = new SimpleBytecodeGen();
    const { bytecode } = gen.generate(code);

    console.log('Bytecode:');
    for (const instr of bytecode) {
      if (instr.arg !== undefined) {
        console.log(`  ${instr.op} ${instr.arg}`);
      } else {
        console.log(`  ${instr.op}`);
      }
    }
    console.log('');

    const runtime = new SimpleRuntime();
    const result = runtime.execute(bytecode);

    console.log('출력:');
    console.log(result.output || '(없음)');

    if (expected && result.output.includes(String(expected))) {
      console.log(`✅ PASS (기대값: ${expected})`);
    } else if (expected) {
      console.log(`❌ FAIL (기대값: ${expected})`);
    }
  } catch (error) {
    console.log(`❌ 오류: ${error.message}`);
  }
}

// 테스트 케이스
test(
  '산술: 10 + 20',
  `INT x = 10
INT y = 20
INT z = x + y
println(z)`,
  30
);

test(
  '배열 합계',
  `ARR nums = [1, 2, 3, 4, 5]
ARR_SUM nums -> total
println(total)`,
  15
);

test(
  '배열 평균',
  `ARR nums = [10, 20, 30]
ARR_AVG nums -> avg
println(avg)`,
  20
);

test(
  '다중 연산',
  `INT a = 5
INT b = 3
INT sum = a + b
INT prod = a * b
println(sum)
println(prod)`,
  '8\n15'
);

console.log('\n╔════════════════════════════════════════╗');
console.log('║ 파이프라인 완성! ✅                     ║');
console.log('╚════════════════════════════════════════╝\n');

