   273→      this.column += 2;
   274→      this.addToken(V3TokenType.NE, '!=');
   275→      return true;
   276→    }
   277→
   278→    if (ch === '<' && next === '=') {
   279→      this.pos += 2;
   280→      this.column += 2;
   281→      this.addToken(V3TokenType.LE, '<=');
