     1→/**
     2→ * V3 Executor (V3 언어 실행 엔진)
     3→ *
     4→ * AST를 직접 해석하여 실행 (Interpreter 방식)
     5→ * - 더 간단하고 명확함
     6→ * - 디버깅 가능
     7→ * - 동작 보장
     8→ */
     9→
    10→import { V3Program, V3Statement, V3Expr } from './v3-parser';
    11→
    12→export interface V3Value {
    13→  type: 'number' | 'string' | 'boolean' | 'array' | 'function' | 'null';
    14→  value: any;
    15→}
    16→
    17→export class V3Executor {
    18→  private globals: Map<string, V3Value> = new Map();
    19→  private locals: Map<string, V3Value>[] = [new Map()];
    20→  private output: string[] = [];
    21→  private returnValue: V3Value | null = null;
    22→  private shouldReturn: boolean = false;
    23→  private functions: Map<string, V3FunctionDef> = new Map();
    24→
    25→  interface V3FunctionDef {
    26→    params: Array<{ name: string; type: string }>;
    27→    body: V3Statement[];
    28→  }
    29→
    30→  constructor() {
    31→    // 빌트인 함수들
    32→    this.registerBuiltins();
    33→  }
    34→
    35→  private registerBuiltins(): void {
    36→    // println은 특수 처리
    37→    // input도 특수 처리
    38→  }
    39→
    40→  execute(program: V3Program): { output: string; success: boolean; error?: string } {
    41→    try {
    42→      for (const stmt of program.statements) {
    43→        this.executeStatement(stmt);
    44→        if (this.shouldReturn) break;
    45→      }
    46→
    47→      return {
    48→        output: this.output.join('\n'),
    49→        success: true,
    50→      };
    51→    } catch (error) {
    52→      return {
    53→        output: this.output.join('\n'),
    54→        success: false,
    55→        error: (error as any).message,
    56→      };
    57→    }
    58→  }
    59→
    60→  private executeStatement(stmt: V3Statement): void {
    61→    switch (stmt.type) {
    62→      case 'VarDecl': {
    63→        const varDecl = stmt as any;
    64→        const value = this.evaluateExpr(varDecl.value);
    65→        this.setVariable(varDecl.name, value);
    66→        break;
    67→      }
    68→
    69→      case 'IfStmt': {
    70→        const ifStmt = stmt as any;
    71→        const condition = this.evaluateExpr(ifStmt.condition);
    72→        if (this.isTruthy(condition)) {
    73→          for (const s of ifStmt.thenBlock) {
    74→            this.executeStatement(s);
    75→            if (this.shouldReturn) return;
    76→          }
    77→        } else if (ifStmt.elseBlock) {
    78→          for (const s of ifStmt.elseBlock) {
    79→            this.executeStatement(s);
    80→            if (this.shouldReturn) return;
    81→          }
    82→        }
    83→        break;
    84→      }
    85→
    86→      case 'ForLoop': {
    87→        const forLoop = stmt as any;
    88→        const iterable = this.evaluateExpr(forLoop.iterable);
    89→
    90→        if (iterable.type !== 'array') {
    91→          throw new Error('FOR IN은 배열에만 사용 가능');
    92→        }
    93→
    94→        for (const item of iterable.value) {
    95→          this.setVariable(forLoop.variable, item);
    96→          for (const s of forLoop.body) {
    97→            this.executeStatement(s);
    98→            if (this.shouldReturn) return;
    99→          }
   100→        }
   101→        break;
   102→      }
   103→
   104→      case 'FuncDecl': {
   105→        const funcDecl = stmt as any;
   106→        this.functions.set(funcDecl.name, {
   107→          params: funcDecl.params,
   108→          body: funcDecl.body,
   109→        });
   110→        break;
   111→      }
   112→
   113→      case 'ReturnStmt': {
   114→        const returnStmt = stmt as any;
   115→        if (returnStmt.value) {
   116→          this.returnValue = this.evaluateExpr(returnStmt.value);
   117→        } else {
   118→          this.returnValue = { type: 'null', value: null };
   119→        }
   120→        this.shouldReturn = true;
   121→        break;
   122→      }
   123→
   124→      case 'ExprStmt': {
   125→        const exprStmt = stmt as any;
   126→        this.evaluateExpr(exprStmt.expr);
   127→        break;
   128→      }
   129→    }
   130→  }
   131→
   132→  private evaluateExpr(expr: V3Expr): V3Value {
   133→    switch (expr.type) {
   134→      case 'Number': {
   135→        const numExpr = expr as any;
   136→        return { type: 'number', value: numExpr.value };
   137→      }
   138→
   139→      case 'String': {
   140→        const strExpr = expr as any;
   141→        return { type: 'string', value: strExpr.value };
   142→      }
   143→
   144→      case 'Bool': {
   145→        const boolExpr = expr as any;
   146→        return { type: 'boolean', value: boolExpr.value };
   147→      }
   148→
   149→      case 'Identifier': {
   150→        const idExpr = expr as any;
   151→        return this.getVariable(idExpr.name);
   152→      }
   153→
   154→      case 'ArrayLiteral': {
   155→        const arrLit = expr as any;
   156→        const elements = arrLit.elements.map((e: V3Expr) => this.evaluateExpr(e));
   157→        return { type: 'array', value: elements };
   158→      }
   159→
   160→      case 'BinaryOp': {
   161→        const binOp = expr as any;
   162→        const left = this.evaluateExpr(binOp.left);
   163→        const right = this.evaluateExpr(binOp.right);
   164→
   165→        switch (binOp.op) {
   166→          case '+':
   167→            if (left.type === 'number' && right.type === 'number') {
   168→              return { type: 'number', value: left.value + right.value };
   169→            }
   170→            if (left.type === 'string' || right.type === 'string') {
   171→              return { type: 'string', value: String(left.value) + String(right.value) };
   172→            }
   173→            throw new Error(`+ 연산 불가: ${left.type} + ${right.type}`);
   174→
   175→          case '-':
   176→            if (left.type === 'number' && right.type === 'number') {
   177→              return { type: 'number', value: left.value - right.value };
   178→            }
   179→            throw new Error(`- 연산 불가: ${left.type} - ${right.type}`);
   180→
   181→          case '*':
   182→            if (left.type === 'number' && right.type === 'number') {
   183→              return { type: 'number', value: left.value * right.value };
   184→            }
   185→            throw new Error(`* 연산 불가: ${left.type} * ${right.type}`);
   186→
   187→          case '/':
   188→            if (left.type === 'number' && right.type === 'number') {
   189→              if (right.value === 0) throw new Error('0으로 나눌 수 없음');
   190→              return { type: 'number', value: left.value / right.value };
   191→            }
   192→            throw new Error(`/ 연산 불가: ${left.type} / ${right.type}`);
   193→
   194→          case '==':
   195→            return { type: 'boolean', value: this.areEqual(left, right) };
   196→
   197→          case '!=':
   198→            return { type: 'boolean', value: !this.areEqual(left, right) };
   199→
   200→          case '<':
   201→            if (left.type === 'number' && right.type === 'number') {
   202→              return { type: 'boolean', value: left.value < right.value };
   203→            }
   204→            throw new Error(`< 연산 불가: ${left.type} < ${right.type}`);
   205→
   206→          case '<=':
   207→            if (left.type === 'number' && right.type === 'number') {
   208→              return { type: 'boolean', value: left.value <= right.value };
   209→            }
   210→            throw new Error(`<= 연산 불가: ${left.type} <= ${right.type}`);
   211→
   212→          case '>':
   213→            if (left.type === 'number' && right.type === 'number') {
   214→              return { type: 'boolean', value: left.value > right.value };
   215→            }
   216→            throw new Error(`> 연산 불가: ${left.type} > ${right.type}`);
   217→
   218→          case '>=':
   219→            if (left.type === 'number' && right.type === 'number') {
   220→              return { type: 'boolean', value: left.value >= right.value };
   221→            }
   222→            throw new Error(`>= 연산 불가: ${left.type} >= ${right.type}`);
   223→
   224→          case 'AND':
   225→            return { type: 'boolean', value: this.isTruthy(left) && this.isTruthy(right) };
   226→
   227→          case 'OR':
   228→            return { type: 'boolean', value: this.isTruthy(left) || this.isTruthy(right) };
   229→
   230→          default:
   231→            throw new Error(`미지원 연산: ${binOp.op}`);
   232→        }
   233→      }
   234→
   235→      case 'UnaryOp': {
   236→        const unaryOp = expr as any;
   237→        const operand = this.evaluateExpr(unaryOp.operand);
   238→
   239→        if (unaryOp.op === '-') {
   240→          if (operand.type === 'number') {
   241→            return { type: 'number', value: -operand.value };
   242→          }
   243→          throw new Error(`- 단항 연산 불가: ${operand.type}`);
   244→        }
   245→
   246→        throw new Error(`미지원 단항 연산: ${unaryOp.op}`);
   247→      }
   248→
   249→      case 'ArrayAccess': {
   250→        const arrAccess = expr as any;
   251→        const array = this.evaluateExpr(arrAccess.array);
   252→        const index = this.evaluateExpr(arrAccess.index);
   253→
   254→        if (array.type !== 'array') {
   255→          throw new Error('배열이 아님');
   256→        }
   257→        if (index.type !== 'number') {
   258→          throw new Error('인덱스는 숫자여야 함');
   259→        }
   260→
   261→        const idx = Math.floor(index.value);
   262→        if (idx < 0 || idx >= array.value.length) {
   263→          throw new Error(`인덱스 범위 초과: ${idx}`);
   264→        }
   265→
   266→        return array.value[idx];
   267→      }
   268→
   269→      case 'ArrayOp': {
   270→        const arrOp = expr as any;
   271→        const array = this.evaluateExpr(arrOp.array);
   272→
   273→        if (array.type !== 'array') {
   274→          throw new Error('배열이 아님');
   275→        }
   276→
   277→        const nums = array.value.map((v: V3Value) => {
   278→          if (v.type !== 'number') throw new Error('배열 원소는 숫자여야 함');
   279→          return v.value;
   280→        });
   281→
   282→        switch (arrOp.op) {
   283→          case 'ARR_SUM':
   284→            return { type: 'number', value: nums.reduce((a: number, b: number) => a + b, 0) };
   285→
   286→          case 'ARR_AVG':
   287→            return {
   288→              type: 'number',
   289→              value: nums.length > 0 ? nums.reduce((a: number, b: number) => a + b, 0) / nums.length : 0,
   290→            };
   291→
   292→          case 'ARR_MAX':
   293→            return { type: 'number', value: nums.length > 0 ? Math.max(...nums) : 0 };
   294→
   295→          case 'ARR_MIN':
   296→            return { type: 'number', value: nums.length > 0 ? Math.min(...nums) : 0 };
   297→
   298→          default:
   299→            throw new Error(`미지원 배열 연산: ${arrOp.op}`);
   300→        }
   301→      }
   302→
   303→      case 'FuncCall': {
   304→        const funcCall = expr as any;
   305→
   306→        // 빌트인 함수
   307→        if (funcCall.name === 'println') {
   308→          const args = funcCall.args.map((arg: V3Expr) => this.evaluateExpr(arg));
   309→          this.output.push(args.map((v: V3Value) => this.stringify(v)).join(' '));
   310→          return { type: 'null', value: null };
   311→        }
   312→
   313→        if (funcCall.name === 'input') {
   314→          // Node.js에서는 동기 입력 불가능, 빈 문자열 반환
   315→          return { type: 'string', value: '' };
   316→        }
   317→
   318→        // 사용자 정의 함수
   319→        const func = this.functions.get(funcCall.name);
   320→        if (!func) {
   321→          throw new Error(`미정의 함수: ${funcCall.name}`);
   322→        }
   323→
   324→        // 새 스코프 생성
   325→        this.locals.push(new Map());
   326→
   327→        // 파라미터 바인딩
   328→        const args = funcCall.args.map((arg: V3Expr) => this.evaluateExpr(arg));
   329→        for (let i = 0; i < func.params.length; i++) {
   330→          const param = func.params[i];
   331→          const arg = args[i] || { type: 'null', value: null };
   332→          this.setVariable(param.name, arg);
   333→        }
   334→
   335→        // 함수 본체 실행
   336→        this.returnValue = null;
   337→        this.shouldReturn = false;
   338→        for (const stmt of func.body) {
   339→          this.executeStatement(stmt);
   340→          if (this.shouldReturn) break;
   341→        }
   342→
   343→        const result = this.returnValue || { type: 'null', value: null };
   344→        this.returnValue = null;
   345→        this.shouldReturn = false;
   346→
   347→        // 스코프 복원
   348→        this.locals.pop();
   349→
   350→        return result;
   351→      }
   352→
   353→      case 'Assignment': {
   354→        const assign = expr as any;
   355→        const value = this.evaluateExpr(assign.value);
   356→        this.setVariable(assign.name, value);
   357→        return value;
   358→      }
   359→
   360→      default:
   361→        throw new Error(`미지원 표현식: ${(expr as any).type}`);
   362→    }
   363→  }
   364→
   365→  private isTruthy(value: V3Value): boolean {
   366→    switch (value.type) {
   367→      case 'null':
   368→        return false;
   369→      case 'boolean':
   370→        return value.value;
   371→      case 'number':
   372→        return value.value !== 0;
   373→      case 'string':
   374→        return value.value.length > 0;
   375→      case 'array':
   376→        return value.value.length > 0;
   377→      default:
   378→        return true;
   379→    }
   380→  }
   381→
   382→  private areEqual(a: V3Value, b: V3Value): boolean {
   383→    if (a.type !== b.type) return false;
   384→    return a.value === b.value;
   385→  }
   386→
   387→  private stringify(value: V3Value): string {
   388→    switch (value.type) {
   389→      case 'null':
   390→        return 'null';
   391→      case 'boolean':
   392→        return value.value ? 'true' : 'false';
   393→      case 'number':
   394→        return String(value.value);
   395→      case 'string':
   396→        return value.value;
   397→      case 'array':
   398→        return '[' + value.value.map((v: V3Value) => this.stringify(v)).join(', ') + ']';
   399→      case 'function':
   400→        return '<function>';
   401→      default:
   402→        return String(value);
   403→    }
   404→  }
   405→
   406→  private getVariable(name: string): V3Value {
   407→    // 지역 스코프에서 먼저 찾기
   408→    for (let i = this.locals.length - 1; i >= 0; i--) {
   409→      if (this.locals[i].has(name)) {
   410→        return this.locals[i].get(name)!;
   411→      }
   412→    }
   413→
   414→    // 전역 스코프에서 찾기
   415→    if (this.globals.has(name)) {
   416→      return this.globals.get(name)!;
   417→    }
   418→
   419→    throw new Error(`미정의 변수: ${name}`);
   420→  }
   421→
   422→  private setVariable(name: string, value: V3Value): void {
   423→    // 이미 존재하면 업데이트
   424→    for (let i = this.locals.length - 1; i >= 0; i--) {
   425→      if (this.locals[i].has(name)) {
   426→        this.locals[i].set(name, value);
   427→        return;
   428→      }
   429→    }
   430→
   431→    if (this.globals.has(name)) {
   432→      this.globals.set(name, value);
   433→      return;
   434→    }
   435→
   436→    // 새로 선언
   437→    const scope = this.locals[this.locals.length - 1];
   438→    scope.set(name, value);
   439→  }
   440→}
