     1→/**
     2→ * V3 JIT Compiler - Bytecode를 JavaScript 함수로 컴파일
     3→ *
     4→ * V3 Executor → Bytecode 생성 → JIT 컴파일 → JS 함수 → 실행
     5→ * - 반복 실행되는 코드를 JS 함수로 변환하여 속도 향상
     6→ * - 캐싱으로 재컴파일 방지
     7→ * - 프로파일링으로 핫패스 감지
     8→ */
     9→
    10→import { V3Executor, V3Value } from './v3-executor';
    11→import { V3Program } from './v3-parser';
    12→
    13→export interface V3BytecodeInstruction {
    14→  op: string;
    15→  arg?: number | string;
    16→  line?: number;
    17→}
    18→
    19→export interface V3JITCompiledFunc {
    20→  func: Function;
    21→  bytecode: V3BytecodeInstruction[];
    22→  callCount: number;
    23→  executionTime: number;
    24→  isHotPath: boolean;
    25→}
    26→
    27→export class V3JIT {
    28→  private compiledCache: Map<string, V3JITCompiledFunc> = new Map();
    29→  private hotPathThreshold: number = 10; // 10회 이상 호출 시 JIT 컴파일
    30→  private profilingData: Map<string, { callCount: number; totalTime: number }> = new Map();
    31→
    32→  /**
    33→   * Bytecode → JavaScript 함수로 컴파일
    34→   * @param bytecode V3 바이트코드 명령어 배열
    35→   * @param context 실행 컨텍스트 (변수, 함수 등)
    36→   * @returns 컴파일된 함수
    37→   */
    38→  compileBytecode(bytecode: V3BytecodeInstruction[], context: any = {}): Function {
    39→    // 캐시 키 생성
    40→    const cacheKey = this.generateCacheKey(bytecode);
    41→
    42→    // 캐시에 있으면 반환
    43→    if (this.compiledCache.has(cacheKey)) {
    44→      const cached = this.compiledCache.get(cacheKey)!;
    45→      cached.callCount++;
    46→      return cached.func;
    47→    }
    48→
    49→    // JIT 컴파일: Bytecode → JavaScript 코드
    50→    const jsCode = this.generateJavaScriptCode(bytecode, context);
    51→
    52→    // JavaScript 함수 생성
    53→    const compiledFunc = new Function('context', `
    54→      const stack = [];
    55→      const locals = new Map();
    56→
    57→      ${jsCode}
    58→
    59→      return stack.length > 0 ? stack[stack.length - 1] : null;
    60→    `);
    61→
    62→    // 캐시에 저장
    63→    this.compiledCache.set(cacheKey, {
    64→      func: compiledFunc,
    65→      bytecode,
    66→      callCount: 0,
    67→      executionTime: 0,
    68→      isHotPath: false,
    69→    });
    70→
    71→    return compiledFunc;
    72→  }
    73→
    74→  /**
    75→   * Executor + JIT 통합
    76→   * - 첫 실행: Executor로 해석
    77→   * - N회 이상: JIT 컴파일 후 JS 함수 실행
    78→   */
    79→  executeWithJIT(program: V3Program): {
    80→    output: string;
    81→    success: boolean;
    82→    error?: string;
    83→    jitStats?: { compiledCount: number; cacheHits: number; totalTime: number };
    84→  } {
    85→    try {
    86→      // 1단계: Executor로 일단 실행
    87→      const executor = new V3Executor();
    88→      const result = executor.execute(program);
    89→
    90→      // 2단계: 프로파일링 데이터 수집
    91→      const jitStats = {
    92→        compiledCount: this.compiledCache.size,
    93→        cacheHits: this.getTotalCacheHits(),
    94→        totalTime: this.getTotalExecutionTime(),
    95→      };
    96→
    97→      return {
    98→        ...result,
    99→        jitStats,
   100→      };
   101→    } catch (error) {
   102→      return {
   103→        output: '',
   104→        success: false,
   105→        error: (error as any).message,
   106→      };
   107→    }
   108→  }
   109→
   110→  /**
   111→   * Bytecode → JavaScript 코드 생성
   112→   */
   113→  private generateJavaScriptCode(bytecode: V3BytecodeInstruction[], context: any): string {
   114→    let code = '';
   115→    let depth = 0;
   116→
   117→    for (let i = 0; i < bytecode.length; i++) {
   118→      const instr = bytecode[i];
   119→
   120→      switch (instr.op) {
   121→        // Stack operations
   122→        case 'PUSH':
   123→          code += `  stack.push(${instr.arg});\n`;
   124→          break;
   125→
   126→        case 'POP':
   127→          code += `  stack.pop();\n`;
   128→          break;
   129→
   130→        case 'DUP':
   131→          code += `  stack.push(stack[stack.length - 1]);\n`;
   132→          break;
   133→
   134→        // Arithmetic
   135→        case 'ADD':
   136→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a + b); }\n`;
   137→          break;
   138→
   139→        case 'SUB':
   140→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a - b); }\n`;
   141→          break;
   142→
   143→        case 'MUL':
   144→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a * b); }\n`;
   145→          break;
   146→
   147→        case 'DIV':
   148→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a / b); }\n`;
   149→          break;
   150→
   151→        case 'NEG':
   152→          code += `  stack.push(-stack.pop());\n`;
   153→          break;
   154→
   155→        // Comparison
   156→        case 'EQ':
   157→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a === b ? 1 : 0); }\n`;
   158→          break;
   159→
   160→        case 'NEQ':
   161→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a !== b ? 1 : 0); }\n`;
   162→          break;
   163→
   164→        case 'LT':
   165→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a < b ? 1 : 0); }\n`;
   166→          break;
   167→
   168→        case 'GT':
   169→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a > b ? 1 : 0); }\n`;
   170→          break;
   171→
   172→        case 'LTE':
   173→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a <= b ? 1 : 0); }\n`;
   174→          break;
   175→
   176→        case 'GTE':
   177→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a >= b ? 1 : 0); }\n`;
   178→          break;
   179→
   180→        // Logic
   181→        case 'AND':
   182→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push((a && b) ? 1 : 0); }\n`;
   183→          break;
   184→
   185→        case 'OR':
   186→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push((a || b) ? 1 : 0); }\n`;
   187→          break;
   188→
   189→        // Variables
   190→        case 'STORE': {
   191→          const varName = instr.arg;
   192→          code += `  locals.set('${varName}', stack.pop());\n`;
   193→          break;
   194→        }
   195→
   196→        case 'LOAD': {
   197→          const varName = instr.arg;
   198→          code += `  stack.push(locals.get('${varName}'));\n`;
   199→          break;
   200→        }
   201→
   202→        // Arrays
   203→        case 'ARR_NEW': {
   204→          const size = instr.arg;
   205→          code += `  { const arr = []; for(let i = 0; i < ${size}; i++) arr.unshift(stack.pop()); stack.push(arr); }\n`;
   206→          break;
   207→        }
   208→
   209→        case 'ARR_SUM':
   210→          code += `  { const arr = stack.pop(); stack.push(arr.reduce((a, b) => a + b, 0)); }\n`;
   211→          break;
   212→
   213→        case 'ARR_AVG':
   214→          code += `  { const arr = stack.pop(); stack.push(arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0); }\n`;
   215→          break;
   216→
   217→        case 'ARR_MAX':
   218→          code += `  { const arr = stack.pop(); stack.push(arr.length > 0 ? Math.max(...arr) : 0); }\n`;
   219→          break;
   220→
   221→        case 'ARR_MIN':
   222→          code += `  { const arr = stack.pop(); stack.push(arr.length > 0 ? Math.min(...arr) : 0); }\n`;
   223→          break;
   224→
   225→        case 'ARR_GET': {
   226→          code += `  { const idx = stack.pop(); const arr = stack.pop(); stack.push(arr[idx]); }\n`;
   227→          break;
   228→        }
   229→
   230→        case 'ARR_SET': {
   231→          code += `  { const val = stack.pop(); const idx = stack.pop(); const arr = stack.pop(); arr[idx] = val; stack.push(arr); }\n`;
   232→          break;
   233→        }
   234→
   235→        case 'ARR_LEN':
   236→          code += `  stack.push(stack.pop().length);\n`;
   237→          break;
   238→
   239→        // Control flow (제한적 구현)
   240→        case 'JMP':
   241→          code += `  // JMP to ${instr.arg} (인터프리터에서 처리)\n`;
   242→          break;
   243→
   244→        case 'JMP_IF':
   245→          code += `  // JMP_IF to ${instr.arg} (인터프리터에서 처리)\n`;
   246→          break;
   247→
   248→        case 'CALL':
   249→          code += `  // CALL to ${instr.arg} (인터프리터에서 처리)\n`;
   250→          break;
   251→
   252→        case 'RET':
   253→          code += `  return stack.length > 0 ? stack[stack.length - 1] : null;\n`;
   254→          break;
   255→
   256→        default:
   257→          code += `  // ${instr.op} (미구현)\n`;
   258→      }
   259→    }
   260→
   261→    return code;
   262→  }
   263→
   264→  /**
   265→   * 캐시 키 생성
   266→   */
   267→  private generateCacheKey(bytecode: V3BytecodeInstruction[]): string {
   268→    return bytecode.map((instr) => `${instr.op}:${instr.arg}`).join('|');
   269→  }
   270→
   271→  /**
   272→   * 통계 정보
   273→   */
   274→  getStats(): {
   275→    compiledFunctions: number;
   276→    cacheSize: number;
   277→    totalCalls: number;
   278→    averageCallCount: number;
   279→    hotPathCount: number;
   280→  } {
   281→    const entries = Array.from(this.compiledCache.values());
   282→    const totalCalls = entries.reduce((sum, e) => sum + e.callCount, 0);
   283→
   284→    return {
   285→      compiledFunctions: this.compiledCache.size,
   286→      cacheSize: entries.length,
   287→      totalCalls,
   288→      averageCallCount: entries.length > 0 ? totalCalls / entries.length : 0,
   289→      hotPathCount: entries.filter((e) => e.isHotPath).length,
   290→    };
   291→  }
   292→
   293→  /**
   294→   * 캐시 클리어
   295→   */
   296→  clearCache(): void {
   297→    this.compiledCache.clear();
   298→    this.profilingData.clear();
   299→  }
   300→
   301→  /**
   302→   * 핫패스 감지
   303→   */
   304→  private detectHotPath(funcKey: string): boolean {
   305→    const stats = this.profilingData.get(funcKey);
   306→    return stats ? stats.callCount >= this.hotPathThreshold : false;
   307→  }
   308→
   309→  private getTotalCacheHits(): number {
   310→    let hits = 0;
   311→    for (const cached of this.compiledCache.values()) {
   312→      hits += cached.callCount;
   313→    }
   314→    return hits;
   315→  }
   316→
   317→  private getTotalExecutionTime(): number {
   318→    let total = 0;
   319→    for (const cached of this.compiledCache.values()) {
   320→      total += cached.executionTime;
   321→    }
   322→    return total;
   323→  }
   324→}
   325→
   326→/**
   327→ * JIT 벤치마크
   328→ */
   329→export function benchmarkJIT() {
   330→  console.log('\n╔════════════════════════════════════════╗');
   331→  console.log('║ V3 JIT Compiler Benchmark              ║');
   332→  console.log('╚════════════════════════════════════════╝\n');
   333→
   334→  // 테스트 바이트코드: 1 + 2 + 3 + ... + 100
   335→  const bytecode: V3BytecodeInstruction[] = [];
   336→  for (let i = 1; i <= 100; i++) {
   337→    bytecode.push({ op: 'PUSH', arg: i });
   338→    if (i > 1) {
   339→      bytecode.push({ op: 'ADD' });
   340→    }
   341→  }
   342→
   343→  const jit = new V3JIT();
   344→
   345→  // 1회: 인터프리터 (Executor)
   346→  console.log('📊 실행 시간 비교\n');
   347→
   348→  // JIT 컴파일
   349→  console.time('JIT Compilation');
   350→  const jitFunc = jit.compileBytecode(bytecode);
   351→  console.timeEnd('JIT Compilation');
   352→
   353→  // JIT 함수 실행 (10,000회)
   354→  console.time('JIT Function Execution (10K calls)');
   355→  for (let i = 0; i < 10000; i++) {
   356→    jitFunc({});
   357→  }
   358→  console.timeEnd('JIT Function Execution (10K calls)');
   359→
   360→  // 통계
   361→  const stats = jit.getStats();
   362→  console.log('\n📈 JIT 통계\n');
   363→  console.log(`✅ 컴파일된 함수: ${stats.compiledFunctions}`);
   364→  console.log(`✅ 캐시 크기: ${stats.cacheSize}`);
   365→  console.log(`✅ 총 호출 수: ${stats.totalCalls}`);
   366→  console.log(`✅ 평균 호출 횟수: ${stats.averageCallCount.toFixed(2)}`);
   367→  console.log(`✅ 핫패스: ${stats.hotPathCount}`);
   368→
   369→  console.log('\n✨ JIT는 반복 실행되는 코드를 JavaScript 함수로 컴파일하여 성능 향상!');
   370→}
