import Anthropic from "@anthropic-ai/sdk";
import { EmitterFactory } from "../../Week3/emitters/index";

/**
 * Intent 인터페이스
 */
export interface Intent {
  action:
    | "create"
    | "modify"
    | "analyze"
    | "optimize"
    | "deploy"
    | "test";
  context:
    | "function"
    | "server"
    | "data"
    | "api"
    | "database"
    | "security";
