import { V5IntentParser, Intent, V4Spec } from "../../Week2/src/v5-intent-parser";
import { V4FormatConverter } from "../../Week2/src/v4-format-converter";
import { ValidationEngine } from "../../Week2/src/validation-engine";
import { EmitterFactory } from "../../Week3/emitters/index";
import {
  ASTOptimizer,
  TypeInference,
} from "../../Week4/optimizers/index";
import { SecurityValidator } from "../../Week4/validators/security-validator";

/**
 * FreeLang v5 파이프라인 결과
 */
export interface PipelineResult {
  success: boolean;
  intent: Intent;
  v4Spec: V4Spec;
  generatedCode: {
    language: string;
    code: string;
  }[];
  optimized: {
    language: string;
    optimizedCode: string;
    improvements: string[];
  }[];
  securityReport: {
    score: number;
    issues: string[];
    recommendations: string[];
  };
  executionTime: number;
  metadata: {
    timestamp: number;
    version: string;
    model: string;
  };
}

/**
 * V5Pipeline: 전체 파이프라인 실행
 */
export class V5Pipeline {
  private intentParser: V5IntentParser;
  private v4Converter: V4FormatConverter;
  private validationEngine: ValidationEngine;
  private emitterFactory: EmitterFactory;
  private astOptimizer: ASTOptimizer;
  private typeInference: TypeInference;
  private securityValidator: SecurityValidator;

  private supportedLanguages: string[] = [
    "typescript",
    "c",
    "python",
    "go",
    "rust",
  ];

  constructor(apiKey?: string) {
    this.intentParser = new V5IntentParser(apiKey);
    this.v4Converter = new V4FormatConverter();
    this.validationEngine = new ValidationEngine();
    this.emitterFactory = new EmitterFactory();
    this.astOptimizer = new ASTOptimizer();
    this.typeInference = new TypeInference();
    this.securityValidator = new SecurityValidator();
  }

  /**
   * 전체 파이프라인 실행
   * @param userInput 사용자의 자연어 의도
   * @param languages 생성할 언어들 (기본: 모든 언어)
   */
  async execute(
    userInput: string,
    languages: string[] = this.supportedLanguages
  ): Promise<PipelineResult> {
    const startTime = Date.now();

    try {
      console.log("\n🚀 FreeLang v5 파이프라인 시작");
      console.log(`📝 사용자 입력: "${userInput}"`);

      // Step 1️⃣: Intent 파싱 (자연어 → Intent AST)
      console.log("\n⏳ Step 1: Intent 파싱...");
      const intent = await this.intentParser.parseIntent(userInput);
      console.log(`✅ Intent 생성: action="${intent.action}", context="${intent.context}"`);

      // Step 2️⃣: v4 형식 변환 (Intent → v4)
      console.log("\n⏳ Step 2: v4 형식 변환...");
      const v4Spec = this.v4Converter.convert(intent);
      const v4Valid = this.validationEngine.validate(v4Spec);
      if (!v4Valid.valid) {
        throw new Error(`v4 검증 실패: ${v4Valid.errors.join(", ")}`);
      }
      console.log("✅ v4 형식 생성 완료");

      // Step 3️⃣: 다국어 코드 생성 (v4 → 언어별 코드)
      console.log("\n⏳ Step 3: 다국어 코드 생성...");
      const generatedCode = this.generateMultiLanguageCode(v4Spec, languages);
      console.log(`✅ ${languages.length}개 언어 코드 생성 완료`);

      // Step 4️⃣: AST 최적화 및 타입 추론
      console.log("\n⏳ Step 4: AST 최적화 및 타입 강화...");
      const optimized = this.optimizeAndEnhance(generatedCode);
      console.log("✅ 최적화 완료");

      // Step 5️⃣: 보안 검증
      console.log("\n⏳ Step 5: 보안 검증...");
      const securityReport = this.validateSecurity(generatedCode);
      console.log(`✅ 보안 점수: ${securityReport.score}/100`);

      const executionTime = Date.now() - startTime;

      const result: PipelineResult = {
        success: true,
        intent,
        v4Spec,
        generatedCode,
        optimized,
        securityReport,
        executionTime,
        metadata: {
          timestamp: Date.now(),
          version: "5.0.0-alpha",
          model: "claude-opus-4-6",
        },
      };

      console.log(`\n✨ 파이프라인 완료! (${executionTime}ms)`);
      return result;
    } catch (error) {
      console.error("❌ 파이프라인 실패:", error);
      throw error;
    }
  }

  /**
   * Step 3: 다국어 코드 생성
   */
  private generateMultiLanguageCode(
    spec: V4Spec,
    languages: string[]
  ): Array<{ language: string; code: string }> {
    return languages.map((lang) => {
      const emitter = this.emitterFactory.createEmitter(lang);
      const code = emitter.emit(spec);
      console.log(`  ✓ ${lang} 코드 생성 완료 (${code.length} bytes)`);
      return { language: lang, code };
    });
  }

  /**
   * Step 4: 최적화 및 타입 강화
   */
  private optimizeAndEnhance(
    generatedCode: Array<{ language: string; code: string }>
  ): Array<{ language: string; optimizedCode: string; improvements: string[] }> {
    return generatedCode.map(({ language, code }) => {
      // AST 최적화
      const optimized = this.astOptimizer.optimize(code);

      // 타입 강화
      const enhanced = this.typeInference.enhance(optimized);

      // 개선 사항 추출
      const improvements = [];
      if (optimized.length < code.length) {
        const saved = code.length - optimized.length;
        improvements.push(`코드 크기 ${saved}bytes 감소 (${((saved / code.length) * 100).toFixed(1)}%)`);
      }
      improvements.push("타입 추론 완료");
      improvements.push("상수 폴딩 적용");

      return {
        language,
        optimizedCode: enhanced,
        improvements,
      };
    });
  }

  /**
   * Step 5: 보안 검증
   */
  private validateSecurity(
    generatedCode: Array<{ language: string; code: string }>
  ): {
    score: number;
    issues: string[];
    recommendations: string[];
  } {
    const allIssues: string[] = [];
    let totalScore = 100;

    // 모든 언어의 코드를 검증
    for (const { language, code } of generatedCode) {
      const result = this.securityValidator.validate(code);
      allIssues.push(...result.issues);
      totalScore = Math.min(totalScore, result.securityScore);
    }

    return {
      score: totalScore,
      issues: [...new Set(allIssues)], // 중복 제거
      recommendations: this.generateSecurityRecommendations(totalScore),
    };
  }

  /**
   * 보안 점수에 따른 권장사항 생성
   */
  private generateSecurityRecommendations(score: number): string[] {
    const recommendations: string[] = [];

    if (score >= 90) {
      recommendations.push("✅ 보안 상태 우수 - 프로덕션 배포 가능");
    } else if (score >= 80) {
      recommendations.push("⚠️ 보안 상태 양호 - 미미한 개선 권장");
      recommendations.push("• 입력 검증 강화 검토");
    } else if (score >= 60) {
      recommendations.push("🔴 보안 상태 중간 - 개선 권장");
      recommendations.push("• SQL Injection 방어 강화");
      recommendations.push("• XSS 방어 추가");
      recommendations.push("• 인증/인가 검토");
    } else {
      recommendations.push("🚨 보안 상태 위험 - 즉시 개선 필수");
      recommendations.push("• 민감 정보 하드코딩 제거");
      recommendations.push("• 보안 전문가 검토 필수");
    }

    return recommendations;
  }

  /**
   * 파이프라인 결과를 포맷된 문자열로 변환
   */
  static formatResult(result: PipelineResult): string {
    let output = `
════════════════════════════════════════════════════════════════════
🎉 FreeLang v5 파이프라인 결과
════════════════════════════════════════════════════════════════════

📊 Intent 분석
─────────────────────────────────────────────────────────────────────
  • Action: ${result.intent.action}
  • Context: ${result.intent.context}
  • Parameters: ${JSON.stringify(result.intent.parameters, null, 2)}

📋 v4 명세
─────────────────────────────────────────────────────────────────────
  • Type: ${result.v4Spec.type}
  • Declarations: ${result.v4Spec.declarations.length}개

💻 생성된 코드
─────────────────────────────────────────────────────────────────────
`;

    for (const { language, code } of result.generatedCode) {
      output += `
  📍 ${language.toUpperCase()} (${code.length} bytes)
  ${"-".repeat(70)}
${code
  .split("\n")
  .slice(0, 5) // 처음 5줄만
  .map((line) => `  ${line}`)
  .join("\n")}
  ... (${code.split("\n").length}줄)
`;
    }

    output += `

🚀 최적화 결과
─────────────────────────────────────────────────────────────────────
`;

    for (const opt of result.optimized) {
      output += `
  📍 ${opt.language.toUpperCase()}
    ${opt.improvements.map((imp) => `✓ ${imp}`).join("\n    ")}
`;
    }

    output += `

🔒 보안 검증
─────────────────────────────────────────────────────────────────────
  • 보안 점수: ${result.securityReport.score}/100
  • 이슈: ${result.securityReport.issues.length}개
  ${result.securityReport.recommendations.map((r) => `• ${r}`).join("\n  ")}

⚡ 성능
─────────────────────────────────────────────────────────────────────
  • 실행 시간: ${result.executionTime}ms
  • 버전: ${result.metadata.version}
  • 모델: ${result.metadata.model}
  • 생성 시간: ${new Date(result.metadata.timestamp).toLocaleString("ko-KR")}

════════════════════════════════════════════════════════════════════
`;

    return output;
  }
}

/**
 * 간단한 테스트용 함수들
 */

/**
 * 테스트: 간단한 함수 생성
 */
export async function testSimpleFunction(): Promise<void> {
  const pipeline = new V5Pipeline();
  const result = await pipeline.execute("두 수의 합을 계산하는 함수를 만들어");
  console.log(V5Pipeline.formatResult(result));
}

/**
 * 테스트: REST API 서버 생성
 */
export async function testRESTServer(): Promise<void> {
  const pipeline = new V5Pipeline();
  const result = await pipeline.execute(
    "사용자 관리 REST API 서버를 만들어. POST /users, GET /users/:id, DELETE /users/:id 엔드포인트"
  );
  console.log(V5Pipeline.formatResult(result));
}

/**
 * 테스트: 데이터 처리
 */
export async function testDataProcessing(): Promise<void> {
  const pipeline = new V5Pipeline();
  const result = await pipeline.execute(
    "배열의 모든 숫자를 제곱하고 합을 구하는 함수"
  );
  console.log(V5Pipeline.formatResult(result));
}

/**
 * 테스트: 모든 언어로 생성
 */
export async function testAllLanguages(): Promise<void> {
  const pipeline = new V5Pipeline();
  const result = await pipeline.execute(
    "Fibonacci 수열을 생성하는 함수",
    ["typescript", "c", "python", "go", "rust"]
  );
  console.log(V5Pipeline.formatResult(result));
}

