 * 사용법:
 *   freelang-v5 "REST API 서버 만들어"
 *   freelang-v5 "두 수의 합 함수" --lang typescript,python,go
 *   freelang-v5 --interactive
 */

import fs from "fs";
import path from "path";
import readline from "readline";
import { V5Pipeline } from "./v5-pipeline";

/**
 * CLI 옵션
 */
interface CLIOptions {
  intent: string;
  languages: string[];
  interactive: boolean;
  output?: string;
  verbose: boolean;
}

/**
 * 커맨드라인 인자 파싱
 */
function parseArgs(): CLIOptions {
  const args = process.argv.slice(2);

  const options: CLIOptions = {
    intent: "",
    languages: ["typescript", "c", "python", "go", "rust"],
    interactive: false,
    verbose: false,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    if (arg === "--interactive" || arg === "-i") {
      options.interactive = true;
    } else if (arg === "--verbose" || arg === "-v") {
      options.verbose = true;
    } else if (arg === "--lang" || arg === "-l") {
      if (i + 1 < args.length) {
        options.languages = args[i + 1].split(",").map((l) => l.trim());
        i++;
      }
    } else if (arg === "--output" || arg === "-o") {
      if (i + 1 < args.length) {
        options.output = args[i + 1];
        i++;
      }
    } else if (!arg.startsWith("-")) {
      options.intent = arg;
    }
  }

  return options;
}

/**
 * 도움말 출력
 */
function showHelp(): void {
  console.log(`
╔════════════════════════════════════════════════════════════════════╗
║         🚀 FreeLang v5 - AI-First Programming Language             ║
║              Intent-Based Code Generation Engine                    ║
╚════════════════════════════════════════════════════════════════════╝

📖 사용법:

  1️⃣  자연어 의도로 코드 생성
      $ freelang-v5 "REST API 서버 만들어"

  2️⃣  특정 언어로만 생성
      $ freelang-v5 "함수 만들어" --lang typescript,python

  3️⃣  대화형 모드
      $ freelang-v5 --interactive

  4️⃣  파일로 저장
      $ freelang-v5 "코드 생성" --output ./generated

🎯 옵션:

  --interactive, -i    대화형 모드 실행
  --lang, -l <langs>   생성할 언어 (쉼표 구분)
                       가능한 값: typescript, c, python, go, rust
  --output, -o <path>  생성된 코드를 파일로 저장
  --verbose, -v        상세 로그 출력
  --help, -h           도움말 표시

💡 예제:

  # 기본 사용
  $ freelang-v5 "두 수의 합 함수"

  # 특정 언어로 생성
  $ freelang-v5 "배열 정렬" --lang go,rust

  # 파일로 저장
  $ freelang-v5 "HTTP 클라이언트" --output ./output

  # 대화형 모드 (연속으로 여러 의도 처리)
  $ freelang-v5 --interactive

🌐 지원 언어:
  • TypeScript (Express.js)
  • C (libuv)
  • Python (FastAPI)
  • Go (net/http)
  • Rust (Actix)

📊 파이프라인:
  자연어 입력
    ↓
  Intent Parser (자연어 → Intent AST)
    ↓
  V4 Format Converter (Intent → v4 메타 명세)
    ↓
  Multi-Language Emitter (5개 언어 코드 생성)
    ↓
  AST Optimizer (최적화)
    ↓
  Type Inference (타입 강화)
    ↓
  Security Validator (보안 검증)
    ↓
  최종 코드 + 리포트

🔑 핵심 기능:
  ✅ AI 기반 Intent 이해 (Claude API)
  ✅ 다국어 자동 코드 생성
  ✅ AST 최적화 (15-20% 코드 감소)
  ✅ 자동 보안 검증
  ✅ 성능 분석 및 개선

📞 지원:
  Issues: https://gogs.dclub.kr/kim/freelang-v5-ai/issues
  Docs: https://gogs.dclub.kr/kim/freelang-v5-ai/wiki

---
Version: 5.0.0-alpha | FreeLang by KimNexus
`);
}

/**
 * 대화형 모드
 */
async function runInteractive(): Promise<void> {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  const pipeline = new V5Pipeline();

  console.log(`
╔════════════════════════════════════════════════════════════════════╗
║            🚀 FreeLang v5 대화형 모드 (Interactive)                ║
╚════════════════════════════════════════════════════════════════════╝

💬 자연어 의도를 입력하세요 (종료: 'quit' 또는 'exit'):
`);

  const askIntent = (): void => {
    rl.question("\n📝 의도> ", async (input) => {
      if (input.toLowerCase() === "quit" || input.toLowerCase() === "exit") {
        console.log("\n👋 FreeLang v5를 사용해주셔서 감사합니다!\n");
        rl.close();
        return;
      }

      if (!input.trim()) {
        askIntent();
        return;
      }

      try {
        console.log(`\n⏳ "${input}"에 대해 파이프라인 실행 중...\n`);
        const result = await pipeline.execute(input);
        console.log(V5Pipeline.formatResult(result));
      } catch (error) {
        console.error(`\n❌ 오류: ${error instanceof Error ? error.message : String(error)}\n`);
      }

      askIntent();
    });
  };

  askIntent();
}

/**
 * 단일 실행 모드
 */
async function runSingle(options: CLIOptions): Promise<void> {
  if (!options.intent) {
    showHelp();
    process.exit(1);
  }

  try {
    console.log(`\n🚀 FreeLang v5 파이프라인 실행`);
    console.log(`📝 의도: "${options.intent}"`);
    console.log(`🌐 언어: ${options.languages.join(", ")}\n`);

    const pipeline = new V5Pipeline();
    const result = await pipeline.execute(options.intent, options.languages);

    // 콘솔에 출력
    console.log(V5Pipeline.formatResult(result));

    // 파일로 저장 옵션
    if (options.output) {
      saveToFiles(options.output, result);
    }
  } catch (error) {
    console.error(`\n❌ 오류: ${error instanceof Error ? error.message : String(error)}`);
    process.exit(1);
  }
}

/**
 * 생성된 코드를 파일로 저장
 */
function saveToFiles(
  outputDir: string,
  result: any
): void {
  try {
    // 디렉토리 생성
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    // 메타데이터 저장
    const metaPath = path.join(outputDir, "meta.json");
    fs.writeFileSync(
      metaPath,
      JSON.stringify(
        {
          intent: result.intent,
          timestamp: result.metadata.timestamp,
          version: result.metadata.version,
          executionTime: result.executionTime,
        },
        null,
        2
      )
    );
    console.log(`\n📄 메타데이터: ${metaPath}`);

    // 각 언어별 코드 저장
    for (const { language, code } of result.generatedCode) {
      const ext = getFileExtension(language);
      const filePath = path.join(outputDir, `generated.${ext}`);
      fs.writeFileSync(filePath, code);
      console.log(`📄 ${language}: ${filePath}`);
    }

    // 보안 리포트 저장
    const securityPath = path.join(outputDir, "security-report.json");
    fs.writeFileSync(
      securityPath,
      JSON.stringify(result.securityReport, null, 2)
    );
    console.log(`📄 보안 리포트: ${securityPath}`);

    console.log(`\n✅ 모든 파일이 ${outputDir}에 저장되었습니다.`);
  } catch (error) {
    console.error(`⚠️  파일 저장 실패: ${error instanceof Error ? error.message : String(error)}`);
  }
}

/**
 * 언어별 파일 확장자
 */
function getFileExtension(language: string): string {
  const extensions: Record<string, string> = {
    typescript: "ts",
    c: "c",
    python: "py",
    go: "go",
    rust: "rs",
  };
  return extensions[language] || "txt";
}

/**
 * Main
 */
async function main(): Promise<void> {
  const args = process.argv.slice(2);

  // --help 또는 -h 확인
  if (args.includes("--help") || args.includes("-h")) {
    showHelp();
    process.exit(0);
  }

  // 아무 인자도 없으면 도움말 표시
  if (args.length === 0) {
    showHelp();
    process.exit(0);
  }

  const options = parseArgs();

  if (options.interactive) {
    await runInteractive();
  } else {
    await runSingle(options);
  }
}

// 실행
main().catch((error) => {
  console.error(`\n❌ 치명적 오류: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
});

