/**
 * FreeLang v5 End-to-End Integration Test
 *
 * 전체 파이프라인 검증:
 * 자연어 의도 → Intent Parser → v4 Format → Code Generator → Optimizer → 보안 검증
 */

import { V5Pipeline, PipelineResult } from "./src/v5-pipeline";

