/**
 * 테스트 결과 수집
 */
interface TestResult {
  testId: number;
  testName: string;
  passed: boolean;
  checks: {
    intentParsed: boolean;
    v4SpecGenerated: boolean;
    codeGenerated: boolean;
    codesValid: boolean;
    optimized: boolean;
    securityValidated: boolean;
  };
  metrics: {
    executionTime: number;
    codeSize: number;
    securityScore: number;
  };
  error?: string;
}

/**
 * 테스트 실행기
 */
class V5E2ETester {
  private pipeline: V5Pipeline;
  private results: TestResult[] = [];

  constructor(apiKey?: string) {
    this.pipeline = new V5Pipeline(apiKey);
  }

  /**
   * 전체 테스트 실행
   */
  async runAllTests(): Promise<void> {
    console.log(`
╔════════════════════════════════════════════════════════════════════╗
║       📊 FreeLang v5 End-to-End 통합 테스트 시작                    ║
║                                                                    ║
║  총 ${TEST_CASES.length}개 테스트 케이스 (10개 Intent 시나리오)                ║
╚════════════════════════════════════════════════════════════════════╝
`);

    for (const testCase of TEST_CASES) {
      console.log(`\n${"=".repeat(70)}`);
      console.log(`Test #${testCase.id}: ${testCase.name}`);
      console.log(`Intention: "${testCase.intent}"`);
      console.log(`Expected Languages: ${testCase.expectedLanguages.join(", ")}`);
      console.log(`${"=".repeat(70)}`);

      const result = await this.runSingleTest(testCase);
      this.results.push(result);

      // 개별 테스트 결과 출력
      this.printTestResult(result);
    }

    // 최종 요약
    this.printSummary();
  }

  /**
   * 개별 테스트 실행
   */
  private async runSingleTest(testCase: TestCase): Promise<TestResult> {
    const result: TestResult = {
      testId: testCase.id,
      testName: testCase.name,
      passed: false,
      checks: {
        intentParsed: false,
        v4SpecGenerated: false,
        codeGenerated: false,
        codesValid: false,
        optimized: false,
        securityValidated: false,
      },
      metrics: {
        executionTime: 0,
        codeSize: 0,
        securityScore: 0,
      },
    };

    try {
      // 파이프라인 실행
      const startTime = Date.now();
      const pipelineResult = await this.pipeline.execute(
        testCase.intent,
        testCase.expectedLanguages
      );
      result.metrics.executionTime = Date.now() - startTime;

      // 검증 체크
      result.checks.intentParsed = !!pipelineResult.intent;
      result.checks.v4SpecGenerated = !!pipelineResult.v4Spec;
      result.checks.codeGenerated =
        pipelineResult.generatedCode.length === testCase.expectedLanguages.length;
      result.checks.codesValid = pipelineResult.generatedCode.every(
        (c) => c.code && c.code.length > 0
      );
      result.checks.optimized = pipelineResult.optimized.length > 0;
      result.checks.securityValidated = pipelineResult.securityReport.score > 0;

      // 메트릭
      result.metrics.codeSize = pipelineResult.generatedCode.reduce(
        (sum, c) => sum + c.code.length,
        0
      );
      result.metrics.securityScore = pipelineResult.securityReport.score;

      // 모든 체크가 통과했는지 확인
      result.passed = Object.values(result.checks).every((check) => check);
    } catch (error) {
      result.error = error instanceof Error ? error.message : String(error);
      console.error(`  ❌ 테스트 실패: ${result.error}`);
    }

    return result;
  }

  /**
   * 개별 테스트 결과 출력
   */
  private printTestResult(result: TestResult): void {
    const status = result.passed ? "✅ PASS" : "❌ FAIL";
    console.log(`\n${status}`);

    if (result.error) {
      console.log(`  Error: ${result.error}`);
      return;
    }

    console.log(`\n  체크 상태:`);
    console.log(
      `    ${result.checks.intentParsed ? "✓" : "✗"} Intent 파싱`
    );
    console.log(
      `    ${result.checks.v4SpecGenerated ? "✓" : "✗"} v4 명세 생성`
    );
    console.log(
      `    ${result.checks.codeGenerated ? "✓" : "✗"} 다국어 코드 생성`
    );
    console.log(
      `    ${result.checks.codesValid ? "✓" : "✗"} 코드 유효성`
    );
    console.log(
      `    ${result.checks.optimized ? "✓" : "✗"} AST 최적화`
    );
    console.log(
      `    ${result.checks.securityValidated ? "✓" : "✗"} 보안 검증`
    );

    console.log(`\n  메트릭:`);
    console.log(`    실행 시간: ${result.metrics.executionTime}ms`);
    console.log(`    생성 코드 크기: ${result.metrics.codeSize} bytes`);
    console.log(`    보안 점수: ${result.metrics.securityScore}/100`);
  }

  /**
   * 최종 요약
   */
  private printSummary(): void {
    const passed = this.results.filter((r) => r.passed).length;
    const total = this.results.length;
    const passRate = ((passed / total) * 100).toFixed(1);

    console.log(`\n${"=".repeat(70)}`);
    console.log(`\n╔════════════════════════════════════════════════════════════════════╗`);
    console.log(`║                    🎯 최종 테스트 결과                            ║`);
    console.log(`╚════════════════════════════════════════════════════════════════════╝\n`);

    console.log(`  📊 통과: ${passed}/${total} (${passRate}%)`);

    // 각 테스트별 상태
    console.log(`\n  테스트 상태:`);
    this.results.forEach((r) => {
      const icon = r.passed ? "✅" : "❌";
      console.log(`    ${icon} Test #${r.testId}: ${r.testName}`);
    });

    // 통계
    const avgExecutionTime =
      this.results.reduce((sum, r) => sum + r.metrics.executionTime, 0) /
      total;
    const avgCodeSize =
      this.results.reduce((sum, r) => sum + r.metrics.codeSize, 0) / total;
    const avgSecurityScore =
      this.results.reduce((sum, r) => sum + r.metrics.securityScore, 0) /
      total;

    console.log(`\n  📈 평균 메트릭:`);
    console.log(`    • 실행 시간: ${avgExecutionTime.toFixed(2)}ms`);
    console.log(`    • 코드 크기: ${avgCodeSize.toFixed(0)} bytes`);
    console.log(`    • 보안 점수: ${avgSecurityScore.toFixed(1)}/100`);

    // 체크별 통과율
    const checkNames = Object.keys(this.results[0].checks) as Array<
      keyof typeof this.results[0].checks
    >;
    console.log(`\n  체크별 통과율:`);
    checkNames.forEach((checkName) => {
      const checksPassed = this.results.filter(
        (r) => r.checks[checkName]
      ).length;
      const checkPassRate = ((checksPassed / total) * 100).toFixed(1);
      const icon = checkPassRate === "100.0" ? "✅" : "⚠️";
      console.log(`    ${icon} ${checkName}: ${checkPassRate}%`);
    });

    // 최종 평가
    console.log(`\n  🎉 최종 평가:`);
    if (passed === total) {
      console.log(`    ✅ 모든 테스트 통과! v5.0.0 릴리즈 준비 완료!`);
    } else if (passed >= total * 0.9) {
      console.log(`    ⚠️  대부분의 테스트 통과. 일부 항목 점검 필요.`);
    } else {
      console.log(`    ❌ 여러 테스트 실패. 구현 검토 필수.`);
    }

    console.log(`\n${"=".repeat(70)}\n`);
  }

  /**
   * JSON 형식으로 결과 출력
   */
  printJSON(): void {
    console.log(
      JSON.stringify(
        {
          summary: {
            total: this.results.length,
            passed: this.results.filter((r) => r.passed).length,
            failed: this.results.filter((r) => !r.passed).length,
            passRate: (
              (this.results.filter((r) => r.passed).length /
                this.results.length) *
              100
            ).toFixed(1),
          },
          results: this.results,
        },
        null,
        2
      )
    );
  }
}

/**
 * 메인 실행
 */
async function main(): Promise<void> {
  const tester = new V5E2ETester();
  await tester.runAllTests();

  // JSON 결과는 별도로 저장
  // tester.printJSON();
}

// 실행
if (require.main === module) {
  main().catch((error) => {
    console.error(`\n❌ 테스트 실패:`, error);
    process.exit(1);
  });
}

export { V5E2ETester, TestCase, TestResult };
